U11_EXERCISES = [{'id': 'u11_ex1', 'unitId': 11, 'page': 35, 'title': 'Latihan 1: Memberi Saran dengan should (Audio TR 16)', 'instruction': 'Dengarkan rekaman TR 16 yang memuat masalah sehari-hari (1-10) dan pasangkan dengan saran (should) yang paling tepat.', 'type': 'choice', 'audioTrack': 'TR 16', 'questions': [{'q': "1. I've got the flu. &rarr; [BLANK]", 'options': ['You should stay in bed.', 'You should buy new shoes.', 'You should take a taxi.', 'You should open the window.'], 'answer': 'You should stay in bed.', 'hint': 'Saat terkena flu, istirahat di ranjang adalah yang terbaik.', 'explanation': "Audio TR 16: 'I've got the flu. You should stay in bed.'"}, {'q': '2. My feet hurt. &rarr; [BLANK]', 'options': ['You should buy new shoes.', 'You should eat something for breakfast.', 'You should pay more attention.', 'You should open the window.'], 'answer': 'You should buy new shoes.', 'hint': 'Kaki sakit sering disebabkan oleh sepatu yang tidak pas.', 'explanation': "Audio TR 16: 'My feet hurt. You should buy new shoes.'"}, {'q': '3. This jacket is too tight. &rarr; [BLANK]', 'options': ['You should buy a new one.', 'You should go to bed earlier.', 'You should stay in bed.', 'You should take a taxi.'], 'answer': 'You should buy a new one.', 'hint': 'Jaket yang terlalu sempit perlu diganti dengan yang baru.', 'explanation': "Audio TR 16: 'This jacket is too tight. You should buy a new one.'"}, {'q': "4. I'm always tired in the morning. &rarr; [BLANK]", 'options': ['You should go to bed earlier.', 'You should buy her some flowers.', 'You should try exercising more.', 'You should take a taxi.'], 'answer': 'You should go to bed earlier.', 'hint': 'Lelah di pagi hari diatasi dengan tidur lebih awal di malam hari.', 'explanation': "Audio TR 16: 'I'm always tired in the morning. You should go to bed earlier.'"}, {'q': "5. I'm too fat. &rarr; [BLANK]", 'options': ['You should try exercising more.', 'You should open the window.', 'You should buy a new one.', 'You should stay in bed.'], 'answer': 'You should try exercising more.', 'hint': 'Olahraga membantu menurunkan berat badan.', 'explanation': "Audio TR 16: 'I'm too fat. You should try exercising more.'"}, {'q': "6. I don't feel like walking. &rarr; [BLANK]", 'options': ['You should take a taxi.', 'You should pay more attention.', 'You should eat something.', 'You should stay in bed.'], 'answer': 'You should take a taxi.', 'hint': 'Jika malas berjalan kaki, gunakan taksi.', 'explanation': "Audio TR 16: 'I don't feel like walking. You should take a taxi.'"}, {'q': "7. I don't remember what the teacher said. &rarr; [BLANK]", 'options': ['You should pay more attention.', 'You should buy new shoes.', 'You should open the window.', 'You should go to bed earlier.'], 'answer': 'You should pay more attention.', 'hint': 'Perhatikan guru saat menjelaskan di kelas.', 'explanation': "Audio TR 16: 'I don't remember what the teacher said. You should pay more attention.'"}, {'q': "8. I'm hungry. &rarr; [BLANK]", 'options': ['You should eat something for breakfast.', 'You should try exercising more.', 'You should buy her some flowers.', 'You should take a taxi.'], 'answer': 'You should eat something for breakfast.', 'hint': 'Lapar diatasi dengan makan sarapan.', 'explanation': "Audio TR 16: 'I'm hungry. You should eat something for breakfast.'"}, {'q': "9. I'm hot. &rarr; [BLANK]", 'options': ['You should open the window.', 'You should stay in bed.', 'You should buy a new one.', 'You should pay more attention.'], 'answer': 'You should open the window.', 'hint': 'Buka jendela agar ruangan menjadi sejuk.', 'explanation': "Audio TR 16: 'I'm hot. You should open the window.'"}, {'q': "10. Tomorrow is my mother's birthday. &rarr; [BLANK]", 'options': ['You should buy her some flowers.', 'You should go to bed earlier.', 'You should eat something.', 'You should take a taxi.'], 'answer': 'You should buy her some flowers.', 'hint': 'Hadiah bunga untuk ulang tahun ibu.', 'explanation': "Audio TR 16: 'Tomorrow is my mother's birthday. You should buy her some flowers.'"}]}, {'id': 'u11_ex2', 'unitId': 11, 'page': 35, 'title': "Latihan 2: Melengkapi Kalimat dengan should atau shouldn't", 'instruction': "Lengkapi kalimat berikut dengan should (seharusnya) atau shouldn't (seharusnya tidak) sesuai konteks nasehat yang baik.", 'type': 'fill', 'questions': [{'q': '1. We [BLANK] help the environment by recycling.', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Mendaur ulang adalah perbuatan positif untuk lingkungan.', 'explanation': "Recycling adalah tindakan baik, sehingga menggunakan modal 'should'."}, {'q': "2. You [BLANK] sit in the sun all day. It's bad for your skin.", 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Duduk di terik matahari seharian buruk untuk kulit.', 'explanation': "Karena berbahaya bagi kulit, gunakan bentuk negatif 'shouldn't'."}, {'q': '3. You [BLANK] take warm clothes with you on holiday. The weather is unpredictable.', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Cuaca tidak menentu, maka sebaiknya bawa baju hangat.', 'explanation': "Saran yang dianjurkan: 'You should take warm clothes...'"}, {'q': "4. He [BLANK] eat so many sweets. They're bad for his teeth.", 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Makan terlalu banyak permen merusak gigi.', 'explanation': "Larangan/nasihat pencegahan menggunakan 'shouldn't'."}, {'q': '5. You [BLANK] stay up so late when you have school tomorrow.', 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Begadang sebelum hari sekolah tidak baik.', 'explanation': "Nasihat negatif: 'shouldn't stay up so late'."}, {'q': '6. You [BLANK] brush your teeth three times a day.', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Menyikat gigi secara teratur adalah anjuran kesehatan.', 'explanation': "Saran kebersihan gigi yang baik menggunakan 'should'."}, {'q': '7. You [BLANK] walk home alone in the dark.', 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Berjalan sendirian di tempat gelap berbahaya.', 'explanation': "Nasihat keselamatan: 'You shouldn't walk home alone in the dark.'"}, {'q': "8. Drivers [BLANK] drive carefully when it's raining.", 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Saat hujan jalanan licin, pengemudi harus hati-hati.', 'explanation': "Saran keselamatan mengemudi: 'Drivers should drive carefully...'"}]}, {'id': 'u11_ex3', 'unitId': 11, 'page': 36, 'title': "Latihan 3: should / shouldn't + Kata Kerja dalam Kotak", 'instruction': "Lengkapi kalimat dengan should atau shouldn't dan kata kerja yang sesuai: watch, arrive, touch, wash, drink, study, walk, take, eat, drive.", 'type': 'fill', 'questions': [{'q': "1. You [BLANK] so much television. It's bad for your eyes.", 'answer': "shouldn't watch", 'alternateAnswers': ['should not watch', "Shouldn't watch"], 'hint': 'Kata kerja: watch.', 'explanation': "Nasihat agar tidak terlalu banyak menonton TV: 'shouldn't watch'."}, {'q': '2. We [BLANK] on time for the meeting.', 'answer': 'should arrive', 'alternateAnswers': ['Should arrive'], 'hint': 'Kata kerja: arrive.', 'explanation': "Datang tepat waktu ke pertemuan adalah kewajiban/anjuran: 'should arrive'."}, {'q': "3. You [BLANK] that wire. It's dangerous.", 'answer': "shouldn't touch", 'alternateAnswers': ['should not touch', "Shouldn't touch"], 'hint': 'Kata kerja: touch.', 'explanation': "Kawat berbahaya tidak boleh disentuh: 'shouldn't touch'."}, {'q': '4. He [BLANK] his hands before eating.', 'answer': 'should wash', 'alternateAnswers': ['Should wash'], 'hint': 'Kata kerja: wash.', 'explanation': "Mencuci tangan sebelum makan: 'should wash'."}, {'q': "5. You [BLANK] that water. It isn't clean.", 'answer': "shouldn't drink", 'alternateAnswers': ['should not drink', "Shouldn't drink"], 'hint': 'Kata kerja: drink.', 'explanation': "Air kotor tidak boleh diminum: 'shouldn't drink'."}, {'q': '6. They [BLANK] harder for their exams.', 'answer': 'should study', 'alternateAnswers': ['Should study'], 'hint': 'Kata kerja: study.', 'explanation': "Belajar lebih giat untuk ujian: 'should study'."}, {'q': '7. She [BLANK] on the grass. Look at the sign!', 'answer': "shouldn't walk", 'alternateAnswers': ['should not walk', "Shouldn't walk"], 'hint': 'Kata kerja: walk.', 'explanation': "Ada tanda larangan menginjak rumput: 'shouldn't walk'."}, {'q': '8. You [BLANK] an umbrella with you. It might rain.', 'answer': 'should take', 'alternateAnswers': ['Should take'], 'hint': 'Kata kerja: take.', 'explanation': "Membawa payung sebagai antisipasi hujan: 'should take'."}, {'q': '9. You [BLANK] more fruit and vegetables.', 'answer': 'should eat', 'alternateAnswers': ['Should eat'], 'hint': 'Kata kerja: eat.', 'explanation': "Makan banyak buah dan sayur untuk kesehatan: 'should eat'."}, {'q': '10. He [BLANK] so fast on this narrow road.', 'answer': "shouldn't drive", 'alternateAnswers': ['should not drive', "Shouldn't drive"], 'hint': 'Kata kerja: drive.', 'explanation': "Mengemudi terlalu cepat di jalan sempit berbahaya: 'shouldn't drive'."}]}, {'id': 'u11_ex4', 'unitId': 11, 'page': 36, 'title': "Latihan 4: Melengkapi dengan should atau shouldn't dan Kata Kerja dalam Kurung", 'instruction': "Gunakan should atau shouldn't bersama bentuk dasar kata kerja di dalam tanda kurung.", 'type': 'fill', 'questions': [{'q': '1. You [BLANK] (apologise) to your sister for breaking her toy.', 'answer': 'should apologise', 'alternateAnswers': ['should apologize', 'Should apologise', 'Should apologize'], 'hint': 'Minta maaf kepada saudara perempuanmu.', 'explanation': "Saran sopan: 'should apologise'."}, {'q': '2. We [BLANK] (not be) late for the English lesson.', 'answer': "shouldn't be", 'alternateAnswers': ['should not be', "Shouldn't be"], 'hint': 'Jangan terlambat.', 'explanation': "Bentuk negatif: 'shouldn't be'."}, {'q': '3. He [BLANK] (listen) to what the teacher says.', 'answer': 'should listen', 'alternateAnswers': ['Should listen'], 'hint': 'Dengarkan perkataan guru.', 'explanation': "Saran positif: 'should listen'."}, {'q': '4. You [BLANK] (not spend) all your pocket money on video games.', 'answer': "shouldn't spend", 'alternateAnswers': ['should not spend', "Shouldn't spend"], 'hint': 'Jangan habiskan seluruh uang saku.', 'explanation': "Bentuk negatif: 'shouldn't spend'."}, {'q': '5. They [BLANK] (wear) helmets when they ride their bicycles.', 'answer': 'should wear', 'alternateAnswers': ['Should wear'], 'hint': 'Pakai helm demi keselamatan.', 'explanation': "Saran wajib keselamatan: 'should wear'."}, {'q': '6. You [BLANK] (not swim) in this river. The current is very strong.', 'answer': "shouldn't swim", 'alternateAnswers': ['should not swim', "Shouldn't swim"], 'hint': 'Arus sungai sangat deras.', 'explanation': "Nasihat bahaya: 'shouldn't swim'."}, {'q': '7. I [BLANK] (go) to the dentist about my toothache.', 'answer': 'should go', 'alternateAnswers': ['Should go'], 'hint': 'Pergi ke dokter gigi karena sakit gigi.', 'explanation': "Saran medis pribadi: 'should go'."}, {'q': '8. Visitors [BLANK] (not eat) or drink inside the library.', 'answer': "shouldn't eat", 'alternateAnswers': ['should not eat', "Shouldn't eat"], 'hint': 'Peraturan perpustakaan melarang makan.', 'explanation': "Nasihat kepatuhan aturan: 'shouldn't eat'."}]}, {'id': 'u11_ex5', 'unitId': 11, 'page': 36, 'title': 'Latihan 5: Memberikan Saran pada Situasi Tertentu', 'instruction': "Pilihlah saran terbaik (should / shouldn't) untuk merespons setiap situasi keluhan berikut.", 'type': 'choice', 'questions': [{'q': "1. 'I want to get fit, but I don't know where to start.' &rarr; [BLANK]", 'options': ['You should join a local gym or go jogging regularly.', "You shouldn't eat any vegetables.", 'You should sleep all afternoon.', "You shouldn't drink any water."], 'answer': 'You should join a local gym or go jogging regularly.', 'hint': 'Ingin bugar butuh olahraga teratur.', 'explanation': 'Saran tepat untuk kebugaran adalah bergabung dengan gym atau lari pagi secara teratur.'}, {'q': "2. 'I'm always late for school in the mornings.' &rarr; [BLANK]", 'options': ['You should set an earlier alarm and go to bed on time.', 'You should stay up watching movies till 3 a.m.', "You shouldn't wear your school uniform.", 'You should walk more slowly.'], 'answer': 'You should set an earlier alarm and go to bed on time.', 'hint': 'Bangun pagi dimulai dari pasang alarm lebih awal.', 'explanation': 'Saran mengatasi keterlambatan adalah pasang alarm lebih awal dan tidur tepat waktu.'}, {'q': "3. 'I have a terrible sore throat and I can hardly talk.' &rarr; [BLANK]", 'options': ['You should drink warm tea with honey and rest your voice.', 'You should shout as loudly as possible.', 'You should drink ice-cold soda.', "You shouldn't see a doctor."], 'answer': 'You should drink warm tea with honey and rest your voice.', 'hint': 'Sakit tenggorokan butuh minuman hangat.', 'explanation': 'Teh hangat madu dan mengistirahatkan suara adalah nasehat yang paling tepat.'}, {'q': "4. 'I don't understand our Maths homework at all.' &rarr; [BLANK]", 'options': ['You should ask the teacher or a classmate to explain it.', 'You should throw your Maths book away.', "You shouldn't do any homework ever.", 'You should copy random numbers.'], 'answer': 'You should ask the teacher or a classmate to explain it.', 'hint': 'Jika tidak paham pelajaran, bertanyalah.', 'explanation': 'Bertanya kepada guru atau teman adalah cara terbaik memahami PR.'}, {'q': "5. 'My phone battery drains in just two hours.' &rarr; [BLANK]", 'options': ['You should have the battery checked or replaced at a service centre.', 'You should drop it in water to cool it down.', "You shouldn't charge it ever again.", 'You should buy ten more chargers.'], 'answer': 'You should have the battery checked or replaced at a service centre.', 'hint': 'Baterai bocor perlu diperiksa ke pusat servis.', 'explanation': 'Pilihan logis untuk baterai rusak adalah memeriksakannya atau mengganti baterai.'}, {'q': "6. 'I have an important exam tomorrow and I feel very stressed.' &rarr; [BLANK]", 'options': ["You should review your main notes, relax, and get a good night's sleep.", 'You should panic and drink five cups of coffee.', "You shouldn't go to the exam tomorrow.", 'You should stay awake all night.'], 'answer': "You should review your main notes, relax, and get a good night's sleep.", 'hint': 'Menghadapi ujian butuh ketenangan dan istirahat cukup.', 'explanation': 'Mengulang materi sekilas, rileks, dan tidur nyenyak merupakan kunci performa ujian yang baik.'}]}, {'id': 'u11_ex6', 'unitId': 11, 'page': 37, 'title': 'Latihan 6: Menyusun Kata Acak Menjadi Kalimat Saran', 'instruction': "Susun kata-kata yang diacak berikut menjadi kalimat saran yang benar menggunakan should atau shouldn't.", 'type': 'fill', 'questions': [{'q': '1. to / bed / should / earlier / you / go', 'answer': 'You should go to bed earlier.', 'alternateAnswers': ['you should go to bed earlier.', 'You should go to bed earlier'], 'hint': 'Subjek: You.', 'explanation': 'Pola: You + should + verb (go) + to bed earlier.'}, {'q': "2. shouldn't / talk / you / loudly / so", 'answer': "You shouldn't talk so loudly.", 'alternateAnswers': ["you shouldn't talk so loudly.", "You shouldn't talk so loudly", 'You should not talk so loudly.'], 'hint': 'Subjek: You.', 'explanation': "Pola: You + shouldn't + verb (talk) + so loudly."}, {'q': '3. take / some / we / should / photos', 'answer': 'We should take some photos.', 'alternateAnswers': ['we should take some photos.', 'We should take some photos'], 'hint': 'Subjek: We.', 'explanation': 'Pola: We + should + verb (take) + some photos.'}, {'q': "4. eat / so / they / sweets / shouldn't / many", 'answer': "They shouldn't eat so many sweets.", 'alternateAnswers': ["they shouldn't eat so many sweets.", "They shouldn't eat so many sweets", 'They should not eat so many sweets.'], 'hint': 'Subjek: They.', 'explanation': "Pola: They + shouldn't + verb (eat) + so many sweets."}, {'q': '5. medicine / take / this / should / you', 'answer': 'You should take this medicine.', 'alternateAnswers': ['you should take this medicine.', 'You should take this medicine'], 'hint': 'Subjek: You.', 'explanation': 'Pola: You + should + verb (take) + this medicine.'}, {'q': "6. worry / you / shouldn't / too / much", 'answer': "You shouldn't worry too much.", 'alternateAnswers': ["you shouldn't worry too much.", "You shouldn't worry too much", 'You should not worry too much.'], 'hint': 'Subjek: You.', 'explanation': "Pola: You + shouldn't + verb (worry) + too much."}]}, {'id': 'u11_ex7', 'unitId': 11, 'page': 37, 'title': 'Latihan 7: Konsultasi Dokter (Audio TR 17)', 'instruction': 'Dengarkan 3 rekaman percakapan pasien dengan dokter pada audio TR 17, lalu jawablah pertanyaan pemahaman berikut.', 'type': 'choice', 'audioTrack': 'TR 17', 'questions': [{'q': "1. Dialogue 1: What is Miss Smith's problem?", 'options': ['She has a terrible headache that started two days ago.', 'She hurt her foot while running.', 'She has a stomach ache.', 'She has lost her glasses.'], 'answer': 'She has a terrible headache that started two days ago.', 'hint': 'Dengarkan awal dialog dokter dengan Miss Smith.', 'explanation': "Miss Smith: 'I have a terrible headache that doesn't seem to go away. It started two days ago.'"}, {'q': '2. Dialogue 1: What advice does the doctor give Miss Smith?', 'options': ['She should take some time off work.', 'She should buy new shoes.', 'She should eat more fast food.', 'She should move house.'], 'answer': 'She should take some time off work.', 'hint': 'Miss Smith mengalami stres kerja.', 'explanation': "Doctor: 'I think you should take some time off work.'"}, {'q': '3. Dialogue 2: What health issues does Mr Kane have?', 'options': ['Bad pains in his back and legs, and he is overweight.', 'A sore throat and fever.', 'An ear infection.', 'A broken arm.'], 'answer': 'Bad pains in his back and legs, and he is overweight.', 'hint': 'Perhatikan keluhan punggung dan berat badan Mr Kane.', 'explanation': "Mr Kane mengeluhkan: 'really bad pains in my back and legs' dan dokter memperhatikan dia overweight."}, {'q': '4. Dialogue 2: What diet advice does the doctor give Mr Kane?', 'options': ["He shouldn't eat burgers and pizza; he should eat lots of fruit and vegetables.", 'He should eat pizza every evening.', 'He should only drink fruit juice.', 'He should stop drinking water.'], 'answer': "He shouldn't eat burgers and pizza; he should eat lots of fruit and vegetables.", 'hint': 'Dokter melarang makanan cepat saji.', 'explanation': "Doctor: 'You shouldn't eat that kind of food. You should eat lots of fruit and vegetables.'"}, {'q': '5. Dialogue 2: How often should Mr Kane exercise?', 'options': ['Twice a week.', 'Every day for three hours.', 'Once a month.', 'Never.'], 'answer': 'Twice a week.', 'hint': 'Dengarkan anjuran frekuensi olahraga di akhir dialog 2.', 'explanation': "Doctor: 'You should start exercising twice a week.'"}, {'q': "6. Dialogue 3: Why can't Janet sleep at night?", 'options': ['She moved house recently and is anxious trying to organise everything alone.', 'Her neighbours are playing loud music.', 'She drinks too much coffee.', 'She is watching TV all night.'], 'answer': 'She moved house recently and is anxious trying to organise everything alone.', 'hint': 'Janet pindah rumah sebulan lalu.', 'explanation': "Janet: 'I moved house about a month ago. And I'm busy trying to organise everything.'"}, {'q': '7. Dialogue 3: What should Janet do according to the doctor?', 'options': ["She should get somebody to help her and shouldn't work until late.", 'She should stay up all night painting.', 'She should buy a new house.', 'She should sleep during the day.'], 'answer': "She should get somebody to help her and shouldn't work until late.", 'hint': 'Dokter menyarankan bantuan orang lain dan istirahat.', 'explanation': "Doctor: 'You should get somebody to help you. And you shouldn't work until late.'"}]}, {'id': 'u11_ex8', 'unitId': 11, 'page': 37, 'title': "Latihan 8: Melengkapi Percakapan dengan should / shouldn't", 'instruction': "Lengkapi teks percakapan berikut dengan memilih should atau shouldn't secara tepat.", 'type': 'fill', 'questions': [{'q': '1. Maya: I want to get better grades in English. What [BLANK] I do?', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': "Pertanyaan meminta saran: 'What should I do?'", 'explanation': "Kalimat tanya meminta nasihat diawali kata modal 'should'."}, {'q': '2. Leo: First, you [BLANK] read English short stories every week.', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Membaca cerita bahasa Inggris adalah saran yang bagus.', 'explanation': "Saran positif menggunakan 'should'."}, {'q': '3. Maya: And what about speaking? Leo: You [BLANK] be afraid of making mistakes.', 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Jangan takut salah saat berbicara.', 'explanation': "Nasihat agar tidak takut: 'shouldn't be afraid'."}, {'q': '4. Leo: You [BLANK] practice speaking with a friend as often as you can.', 'answer': 'should', 'alternateAnswers': ['Should'], 'hint': 'Berlatih berbicara dengan teman sesering mungkin.', 'explanation': "Saran yang dianjurkan: 'should practice'."}, {'q': "5. Maya: That's great advice. I definitely [BLANK] leave my revision until the night before the test!", 'answer': "shouldn't", 'alternateAnswers': ['should not', "Shouldn't"], 'hint': 'Jangan menunda belajar hingga malam sebelum ujian.', 'explanation': "Bentuk larangan/penolakan kebiasaan buruk: 'shouldn't leave'."}]}]

U12_EXERCISES = [{'id': 'u12_ex1', 'unitId': 12, 'page': 38, 'title': 'Latihan 1: Bentuk Past Participle (V3) Kata Kerja', 'instruction': 'Tuliskan bentuk past participle (V3) dari kata kerja tidak beraturan (irregular verbs) berikut.', 'type': 'fill', 'questions': [{'q': '1. be &rarr; [BLANK]', 'answer': 'been', 'alternateAnswers': ['Been'], 'hint': 'Bentuk ketiga dari be (was/were).', 'explanation': 'be &rarr; was/were &rarr; been.'}, {'q': '2. see &rarr; [BLANK]', 'answer': 'seen', 'alternateAnswers': ['Seen'], 'hint': 'Bentuk ketiga dari see (saw).', 'explanation': 'see &rarr; saw &rarr; seen.'}, {'q': '3. do &rarr; [BLANK]', 'answer': 'done', 'alternateAnswers': ['Done'], 'hint': 'Bentuk ketiga dari do (did).', 'explanation': 'do &rarr; did &rarr; done.'}, {'q': '4. go &rarr; [BLANK]', 'answer': 'gone', 'alternateAnswers': ['Gone', 'been'], 'hint': 'Bentuk ketiga dari go (went).', 'explanation': 'go &rarr; went &rarr; gone (atau been jika sudah kembali).'}, {'q': '5. have &rarr; [BLANK]', 'answer': 'had', 'alternateAnswers': ['Had'], 'hint': 'Bentuk ketiga dari have (had).', 'explanation': 'have &rarr; had &rarr; had.'}, {'q': '6. eat &rarr; [BLANK]', 'answer': 'eaten', 'alternateAnswers': ['Eaten'], 'hint': 'Bentuk ketiga dari eat (ate).', 'explanation': 'eat &rarr; ate &rarr; eaten.'}, {'q': '7. make &rarr; [BLANK]', 'answer': 'made', 'alternateAnswers': ['Made'], 'hint': 'Bentuk ketiga dari make (made).', 'explanation': 'make &rarr; made &rarr; made.'}, {'q': '8. write &rarr; [BLANK]', 'answer': 'written', 'alternateAnswers': ['Written'], 'hint': 'Bentuk ketiga dari write (wrote).', 'explanation': 'write &rarr; wrote &rarr; written.'}, {'q': '9. give &rarr; [BLANK]', 'answer': 'given', 'alternateAnswers': ['Given'], 'hint': 'Bentuk ketiga dari give (gave).', 'explanation': 'give &rarr; gave &rarr; given.'}, {'q': '10. take &rarr; [BLANK]', 'answer': 'taken', 'alternateAnswers': ['Taken'], 'hint': 'Bentuk ketiga dari take (took).', 'explanation': 'take &rarr; took &rarr; taken.'}]}, {'id': 'u12_ex2', 'unitId': 12, 'page': 38, 'title': 'Latihan 2: Pengalaman Perjalanan Jessica & Emily (Audio TR 18)', 'instruction': 'Dengarkan percakapan Jessica dan Emily di audio TR 18 mengenai tempat-tempat yang pernah mereka kunjungi, lalu jawablah pertanyaan berikut.', 'type': 'choice', 'audioTrack': 'TR 18', 'questions': [{'q': '1. Which cities has Jessica visited in the United States?', 'options': ['New York and Washington.', 'San Francisco and Los Angeles.', 'San Diego and Chicago.', 'Miami and Boston.'], 'answer': 'New York and Washington.', 'hint': 'Dengarkan jawaban awal Jessica saat ditanya apakah pernah ke US.', 'explanation': "Jessica: 'Well, I've been to New York and Washington. I spent ten days there...'"}, {'q': '2. Has Jessica ever visited San Francisco or Los Angeles?', 'options': ['No, she has never been there.', 'Yes, she spent a month there.', 'Yes, she went there last winter.', 'Yes, she lives there.'], 'answer': 'No, she has never been there.', 'hint': "Jessica menyebutkan 'I've never been to...'", 'explanation': "Jessica: '...but I've never been to San Francisco or Los Angeles.'"}, {'q': '3. Which place in California has Emily stayed in?', 'options': ['San Diego and San Francisco.', 'Sacramento and Hollywood.', 'Beverly Hills.', 'San Jose.'], 'answer': 'San Diego and San Francisco.', 'hint': 'Emily mengatakan San Francisco itu indah dan dia juga pernah tinggal di San Diego.', 'explanation': "Emily: 'San Francisco is beautiful! I've stayed in San Diego, too.'"}, {'q': '4. Has Jessica ever visited Ireland?', 'options': ["No, she hasn't, but Emily has.", 'Yes, she went there with Emily.', 'Yes, two years ago.', 'She was born there.'], 'answer': "No, she hasn't, but Emily has.", 'hint': 'Jessica menjawab pertanyaan Emily tentang Irlandia.', 'explanation': "Jessica: 'No, I haven't. Have you?' Emily: 'Yes, I have. I went a couple of years ago.'"}, {'q': '5. What does Emily think of Ireland compared to California?', 'options': ["It's quite different from California, but just as beautiful.", "It's much hotter than California.", "She didn't like it.", "It's very boring."], 'answer': "It's quite different from California, but just as beautiful.", 'hint': 'Dengarkan pendapat Emily tentang keindahan Irlandia.', 'explanation': "Emily: 'It's quite different from California but it's just as beautiful.'"}]}, {'id': 'u12_ex3', 'unitId': 12, 'page': 39, 'title': 'Latihan 3: Melengkapi Kalimat dengan have / has + Past Participle', 'instruction': 'Lengkapi kalimat dengan bentuk Present Perfect yang tepat menggunakan have atau has dan kata kerja di dalam kurung.', 'type': 'fill', 'questions': [{'q': '1. She [BLANK] (finish) all her homework before dinner.', 'answer': 'has finished', 'alternateAnswers': ['Has finished'], 'hint': 'Subjek she menggunakan has + V3 (-ed).', 'explanation': "She adalah orang ketiga tunggal: 'has finished'."}, {'q': '2. They [BLANK] (live) in this town for ten years.', 'answer': 'have lived', 'alternateAnswers': ['Have lived'], 'hint': 'Subjek they menggunakan have + V3.', 'explanation': "They adalah jamak: 'have lived'."}, {'q': '3. I [BLANK] (lose) my passport! What should I do?', 'answer': 'have lost', 'alternateAnswers': ['Have lost', "I've lost"], 'hint': 'Subjek I, kata kerja lose &rarr; lost.', 'explanation': 'I have lost my passport.'}, {'q': '4. Oliver [BLANK] (buy) a new bicycle for his birthday.', 'answer': 'has bought', 'alternateAnswers': ['Has bought'], 'hint': 'Subjek Oliver (he), kata kerja buy &rarr; bought.', 'explanation': 'Oliver has bought a new bicycle.'}, {'q': '5. We [BLANK] (clean) the kitchen and the living room.', 'answer': 'have cleaned', 'alternateAnswers': ['Have cleaned'], 'hint': 'Subjek we, clean adalah regular verb.', 'explanation': 'We have cleaned the kitchen.'}, {'q': '6. The rain [BLANK] (stop), so we can go outside now.', 'answer': 'has stopped', 'alternateAnswers': ['Has stopped'], 'hint': 'The rain (it) menggunakan has, stop &rarr; stopped.', 'explanation': 'The rain has stopped.'}]}, {'id': 'u12_ex4', 'unitId': 12, 'page': 39, 'title': 'Latihan 4: Penggunaan ever dan never', 'instruction': "Lengkapi kalimat berikut dengan kata 'ever' (pernah - dalam kalimat tanya) atau 'never' (belum pernah - kalimat positif bernilai negatif).", 'type': 'fill', 'questions': [{'q': '1. Have you [BLANK] seen a lion in the wild?', 'answer': 'ever', 'alternateAnswers': ['Ever'], 'hint': 'Digunakan dalam kalimat tanya tentang pengalaman.', 'explanation': "Kalimat tanya pengalaman: 'Have you ever...?'"}, {'q': '2. I have [BLANK] eaten sushi in my whole life.', 'answer': 'never', 'alternateAnswers': ['Never'], 'hint': 'Menyatakan belum pernah sama sekali.', 'explanation': "Bentuk pengalaman belum pernah: 'I have never eaten...'"}, {'q': '3. Has she [BLANK] been to Paris on holiday?', 'answer': 'ever', 'alternateAnswers': ['Ever'], 'hint': 'Kalimat tanya untuk subjek she.', 'explanation': "Pertanyaan pengalaman menggunakan 'ever'."}, {'q': '4. They have [BLANK] flown in an aeroplane before.', 'answer': 'never', 'alternateAnswers': ['Never'], 'hint': 'Menyatakan pertama kali / belum pernah.', 'explanation': 'They have never flown before.'}, {'q': '5. Have you [BLANK] met a famous actor or musician?', 'answer': 'ever', 'alternateAnswers': ['Ever'], 'hint': 'Pertanyaan pengalaman hidup.', 'explanation': 'Have you ever met a famous person?'}, {'q': '6. We have [BLANK] tried rock climbing because we are afraid of heights.', 'answer': 'never', 'alternateAnswers': ['Never'], 'hint': 'Alasannya takut ketinggian, berarti belum pernah mencoba.', 'explanation': 'We have never tried rock climbing.'}]}, {'id': 'u12_ex5', 'unitId': 12, 'page': 39, 'title': "Latihan 5: Membuat Pertanyaan 'Have you ever...?'", 'instruction': "Susun kata-kata petunjuk berikut menjadi pertanyaan pengalaman dengan struktur 'Have you ever + V3...?'", 'type': 'fill', 'questions': [{'q': '1. you / be / to London &rarr; [BLANK]', 'answer': 'Have you ever been to London?', 'alternateAnswers': ['have you ever been to london?', 'Have you ever been to London'], 'hint': 'Kata kerja be menjadi been.', 'explanation': 'Have you ever been to London?'}, {'q': '2. you / ride / a horse &rarr; [BLANK]', 'answer': 'Have you ever ridden a horse?', 'alternateAnswers': ['have you ever ridden a horse?', 'Have you ever ridden a horse'], 'hint': 'Kata kerja ride menjadi ridden.', 'explanation': 'Have you ever ridden a horse?'}, {'q': '3. you / win / a competition &rarr; [BLANK]', 'answer': 'Have you ever won a competition?', 'alternateAnswers': ['have you ever won a competition?', 'Have you ever won a competition'], 'hint': 'Kata kerja win menjadi won.', 'explanation': 'Have you ever won a competition?'}, {'q': '4. you / break / a bone &rarr; [BLANK]', 'answer': 'Have you ever broken a bone?', 'alternateAnswers': ['have you ever broken a bone?', 'Have you ever broken a bone'], 'hint': 'Kata kerja break menjadi broken.', 'explanation': 'Have you ever broken a bone?'}, {'q': '5. you / sleep / in a tent &rarr; [BLANK]', 'answer': 'Have you ever slept in a tent?', 'alternateAnswers': ['have you ever slept in a tent?', 'Have you ever slept in a tent'], 'hint': 'Kata kerja sleep menjadi slept.', 'explanation': 'Have you ever slept in a tent?'}, {'q': '6. you / eat / snails &rarr; [BLANK]', 'answer': 'Have you ever eaten snails?', 'alternateAnswers': ['have you ever eaten snails?', 'Have you ever eaten snails'], 'hint': 'Kata kerja eat menjadi eaten.', 'explanation': 'Have you ever eaten snails?'}]}, {'id': 'u12_ex6', 'unitId': 12, 'page': 40, 'title': 'Latihan 6: Present Perfect Sentences (Audio TR 19)', 'instruction': 'Dengarkan audio TR 19 dan lengkapi kata kerja bentuk past participle (V3) yang hilang pada setiap kalimat yang diucapkan.', 'type': 'fill', 'audioTrack': 'TR 19', 'questions': [{'q': '1. Have you [BLANK] the news?', 'answer': 'heard', 'alternateAnswers': ['Heard'], 'hint': 'Kata kerja: hear.', 'explanation': "Audio TR 19: 'Have you heard the news?'"}, {'q': '2. Has your father [BLANK] for work yet?', 'answer': 'left', 'alternateAnswers': ['Left'], 'hint': 'Kata kerja: leave.', 'explanation': "Audio TR 19: 'Has your father left for work yet?'"}, {'q': '3. Have you [BLANK] dinner yet?', 'answer': 'had', 'alternateAnswers': ['Had'], 'hint': 'Kata kerja: have.', 'explanation': "Audio TR 19: 'Have you had dinner yet?'"}, {'q': '4. How long have you [BLANK] him?', 'answer': 'known', 'alternateAnswers': ['Known'], 'hint': 'Kata kerja: know.', 'explanation': "Audio TR 19: 'How long have you known him?'"}, {'q': '5. How many times have you [BLANK] your grandparents this month?', 'answer': 'visited', 'alternateAnswers': ['Visited'], 'hint': 'Kata kerja: visit.', 'explanation': "Audio TR 19: 'How many times have you visited your grandparents this month?'"}, {'q': '6. Have you ever [BLANK] this programme?', 'answer': 'seen', 'alternateAnswers': ['Seen'], 'hint': 'Kata kerja: see.', 'explanation': "Audio TR 19: 'Have you ever seen this programme?'"}, {'q': "7. I haven't seen Lucy lately. Has she [BLANK] sick?", 'answer': 'been', 'alternateAnswers': ['Been'], 'hint': 'Kata kerja: be.', 'explanation': "Audio TR 19: 'I haven't seen Lucy lately. Has she been sick?'"}, {'q': '8. Have they [BLANK] their parents yet?', 'answer': 'asked', 'alternateAnswers': ['Asked'], 'hint': 'Kata kerja: ask.', 'explanation': "Audio TR 19: 'Have they asked their parents yet?'"}, {'q': '9. How many times has she [BLANK] that film?', 'answer': 'seen', 'alternateAnswers': ['Seen'], 'hint': 'Kata kerja: see.', 'explanation': "Audio TR 19: 'How many times has she seen that film?'"}, {'q': "10. What's that nice smell? Have you [BLANK] perfumes?", 'answer': 'changed', 'alternateAnswers': ['Changed'], 'hint': 'Kata kerja: change.', 'explanation': "Audio TR 19: 'What's that nice smell? Have you changed perfumes?'"}]}, {'id': 'u12_ex7', 'unitId': 12, 'page': 40, 'title': 'Latihan 7: already, yet, dan just', 'instruction': 'Lengkapi kalimat dengan already (sudah), yet (belum / sudah pada tanya), atau just (baru saja).', 'type': 'choice', 'questions': [{'q': '1. I have [BLANK] finished my essay, so I can relax now.', 'options': ['already', 'yet', 'ever', 'since'], 'answer': 'already', 'hint': 'Sudah selesai lebih cepat dari perkiraan.', 'explanation': "'already' diletakkan di antara have dan past participle dalam kalimat positif."}, {'q': '2. Have you called the doctor [BLANK]?', 'options': ['yet', 'just', 'since', 'already'], 'answer': 'yet', 'hint': 'Digunakan di akhir kalimat tanya.', 'explanation': "'yet' biasanya diletakkan di akhir kalimat tanya atau negatif."}, {'q': "3. Be careful! I have [BLANK] washed the floor, and it's still wet.", 'options': ['just', 'yet', 'for', 'ever'], 'answer': 'just', 'hint': 'Baru saja dilakukan sesaat yang lalu.', 'explanation': "'just' berarti baru saja terjadi beberapa saat lalu."}, {'q': "4. We haven't eaten lunch [BLANK]. We are still hungry.", 'options': ['yet', 'already', 'just', 'never'], 'answer': 'yet', 'hint': "Di akhir kalimat negatif bermakna 'belum'.", 'explanation': "'yet' di akhir kalimat negatif berarti 'belum'."}, {'q': "5. Don't tell me what happens in the movie; I haven't seen it [BLANK]!", 'options': ['yet', 'already', 'just', 'for'], 'answer': 'yet', 'hint': 'Belum menontonnya.', 'explanation': "Kalimat negatif berakhiran 'yet'."}, {'q': '6. Look! The postman has [BLANK] delivered a parcel for you.', 'options': ['just', 'yet', 'since', 'never'], 'answer': 'just', 'hint': 'Baru saja mengantarkan paket.', 'explanation': "'has just delivered' = baru saja mengantar."}]}, {'id': 'u12_ex8', 'unitId': 12, 'page': 40, 'title': 'Latihan 8: Membedakan for dan since', 'instruction': 'Pilih for (untuk durasi / lama waktu) atau since (sejak titik awal waktu) untuk setiap penanda waktu berikut.', 'type': 'choice', 'questions': [{'q': '1. I have lived here [BLANK] three years.', 'options': ['for', 'since'], 'answer': 'for', 'hint': 'Three years adalah durasi (periode waktu).', 'explanation': "Durasi waktu memakai 'for'."}, {'q': '2. She has worked at the bank [BLANK] 2018.', 'options': ['since', 'for'], 'answer': 'since', 'hint': '2018 adalah titik awal waktu (tahun).', 'explanation': "Titik waktu tertentu memakai 'since'."}, {'q': "3. They haven't seen each other [BLANK] last Monday.", 'options': ['since', 'for'], 'answer': 'since', 'hint': 'Last Monday adalah hari tertentu di masa lalu.', 'explanation': "Hari/tanggal tertentu memakai 'since'."}, {'q': '4. We have been waiting for the bus [BLANK] two hours.', 'options': ['for', 'since'], 'answer': 'for', 'hint': 'Two hours adalah periode panjang waktu.', 'explanation': "Lama waktu (jam) memakai 'for'."}, {'q': "5. He hasn't eaten anything [BLANK] breakfast.", 'options': ['since', 'for'], 'answer': 'since', 'hint': 'Breakfast adalah titik waktu di pagi hari.', 'explanation': "Titik mula kejadian memakai 'since'."}, {'q': '6. My brother has had that car [BLANK] six months.', 'options': ['for', 'since'], 'answer': 'for', 'hint': 'Six months adalah kurun waktu.', 'explanation': "Kurun waktu (bulan) memakai 'for'."}, {'q': '7. It has been raining [BLANK] yesterday afternoon.', 'options': ['since', 'for'], 'answer': 'since', 'hint': 'Yesterday afternoon adalah titik waktu kemarin siang.', 'explanation': "Titik waktu lampau memakai 'since'."}, {'q': "8. We haven't spoken to them [BLANK] a long time.", 'options': ['for', 'since'], 'answer': 'for', 'hint': "'a long time' adalah rentang waktu yang lama.", 'explanation': "Ungkapan rentang waktu: 'for a long time'."}]}, {'id': 'u12_ex9', 'unitId': 12, 'page': 41, 'title': 'Latihan 9: Present Perfect vs Past Simple', 'instruction': 'Pilihlah bentuk kata kerja yang benar: Past Simple (waktu spesifik di masa lampau) atau Present Perfect (pengalaman/keterkaitan dengan masa kini).', 'type': 'choice', 'questions': [{'q': '1. I [BLANK] Italy last summer with my family.', 'options': ['visited', 'have visited', 'visit', 'was visiting'], 'answer': 'visited', 'hint': "Ada keterangan waktu spesifik 'last summer'.", 'explanation': "'last summer' adalah penanda waktu lampau yang pasti &rarr; gunakan Past Simple: 'visited'."}, {'q': '2. She [BLANK] in Madrid for five years, and she still loves living there.', 'options': ['has lived', 'lived', 'lives', 'was living'], 'answer': 'has lived', 'hint': 'Kegiatan masih berlangsung sampai sekarang.', 'explanation': "Tindakan yang berlanjut hingga kini memakai Present Perfect: 'has lived'."}, {'q': '3. We [BLANK] a brand new car yesterday afternoon.', 'options': ['bought', 'have bought', 'buy', 'were buying'], 'answer': 'bought', 'hint': "'yesterday afternoon' adalah waktu yang sudah selesai.", 'explanation': "Ada kata 'yesterday' &rarr; Past Simple: 'bought'."}, {'q': '4. [BLANK] your homework yet?', 'options': ['Have you finished', 'Did you finish', 'Do you finish', 'Were you finishing'], 'answer': 'Have you finished', 'hint': "Ada kata 'yet' di akhir pertanyaan.", 'explanation': "'yet' berpasangan dengan Present Perfect: 'Have you finished'."}, {'q': '5. They [BLANK] to the cinema on Friday evening.', 'options': ['went', 'have gone', 'go', 'are going'], 'answer': 'went', 'hint': "'on Friday evening' menunjukkan waktu spesifik di masa lalu.", 'explanation': "Waktu lampau tertentu &rarr; Past Simple: 'went'."}, {'q': "6. I [BLANK] sushi, but I'd like to try it one day.", 'options': ['have never tasted', 'never tasted', 'did never taste', 'was never tasting'], 'answer': 'have never tasted', 'hint': 'Membicarakan pengalaman hidup hingga saat ini.', 'explanation': "Pengalaman hidup seumur hidup memakai Present Perfect: 'have never tasted'."}]}, {'id': 'u12_ex10', 'unitId': 12, 'page': 41, 'title': 'Latihan 10: Mengoreksi Kesalahan Kalimat (Error Correction)', 'instruction': 'Pilihlah kalimat perbaikan yang benar untuk membetulkan kesalahan tata bahasa pada setiap kalimat berikut.', 'type': 'choice', 'questions': [{'q': "1. Salah: 'I have seen him yesterday at the supermarket.' &rarr; Benar: [BLANK]", 'options': ['I saw him yesterday at the supermarket.', 'I have saw him yesterday at the supermarket.', 'I see him yesterday at the supermarket.', 'I was seen him yesterday at the supermarket.'], 'answer': 'I saw him yesterday at the supermarket.', 'hint': 'Yesterday tidak boleh memakai have seen.', 'explanation': "Waktu lampau 'yesterday' harus menggunakan Past Simple 'saw'."}, {'q': "2. Salah: 'She didn't finish her project yet.' &rarr; Benar: [BLANK]", 'options': ["She hasn't finished her project yet.", "She haven't finished her project yet.", "She doesn't finish her project yet.", "She isn't finished her project yet."], 'answer': "She hasn't finished her project yet.", 'hint': "Yet berpasangan dengan hasn't finished.", 'explanation': "'yet' dipadukan dengan Present Perfect negatif: 'hasn't finished'."}, {'q': "3. Salah: 'We have lived here since three years.' &rarr; Benar: [BLANK]", 'options': ['We have lived here for three years.', 'We lived here since three years ago.', 'We are living here since three years.', 'We have live here for three years.'], 'answer': 'We have lived here for three years.', 'hint': "Durasi 'three years' memakai for, bukan since.", 'explanation': "Periode waktu tiga tahun harus menggunakan 'for'."}, {'q': "4. Salah: 'Did you ever fly in a helicopter?' &rarr; Benar: [BLANK]", 'options': ['Have you ever flown in a helicopter?', 'Did you ever flown in a helicopter?', 'Have you ever flew in a helicopter?', 'Do you ever flown in a helicopter?'], 'answer': 'Have you ever flown in a helicopter?', 'hint': 'Pertanyaan pengalaman hidup menggunakan Have you ever + V3.', 'explanation': "Pengalaman seumur hidup: 'Have you ever flown...?'"}, {'q': "5. Salah: 'He has already went home.' &rarr; Benar: [BLANK]", 'options': ['He has already gone home.', 'He already went home yet.', 'He is already gone home.', 'He has already go home.'], 'answer': 'He has already gone home.', 'hint': 'Bentuk V3 dari go adalah gone.', 'explanation': "Setelah 'has' harus menggunakan past participle: 'gone', bukan 'went'."}]}, {'id': 'u12_ex11', 'unitId': 12, 'page': 41, 'title': 'Latihan 11: Melengkapi Percakapan dengan Tenses yang Tepat', 'instruction': 'Lengkapi dialog antara Tom dan Anna dengan memilih bentuk yang tepat antara Present Perfect atau Past Simple.', 'type': 'fill', 'questions': [{'q': '1. Tom: [BLANK] (you / ever / be) to Spain?', 'answer': 'Have you ever been', 'alternateAnswers': ['have you ever been'], 'hint': 'Pertanyaan pengalaman hidup.', 'explanation': "Pengalaman: 'Have you ever been to Spain?'"}, {'q': '2. Anna: Yes, I [BLANK] (go) to Barcelona two years ago.', 'answer': 'went', 'alternateAnswers': ['Went'], 'hint': "Keterangan waktu: 'two years ago'.", 'explanation': "'two years ago' adalah waktu lampau spesifik &rarr; Past Simple: 'went'."}, {'q': '3. Tom: Did you like it? Anna: Yes, I [BLANK] (love) the architecture there.', 'answer': 'loved', 'alternateAnswers': ['Loved'], 'hint': 'Bercerita tentang liburan masa lalu tersebut.', 'explanation': "Past Simple: 'loved'."}, {'q': '4. Tom: I [BLANK] (never / visit) Spain, but I really want to go next summer.', 'answer': 'have never visited', 'alternateAnswers': ['have never visited', 'I have never visited'], 'hint': 'Pengalaman seumur hidup Tom belum pernah berkunjung.', 'explanation': "Present Perfect: 'have never visited'."}, {'q': '5. Anna: You should! I [BLANK] (already / book) another trip there for July.', 'answer': 'have already booked', 'alternateAnswers': ['have already booked', "I've already booked"], 'hint': 'Sudah memesan tiket untuk liburan mendatang.', 'explanation': "Present Perfect: 'have already booked'."}]}]

U13_EXERCISES = [{'id': 'u13_ex1', 'unitId': 13, 'page': 42, 'title': 'Latihan 1: Countable vs Uncountable Nouns', 'instruction': 'Tentukan apakah kata benda berikut tergolong Countable (dapat dihitung) atau Uncountable (tidak dapat dihitung).', 'type': 'choice', 'questions': [{'q': '1. water &rarr; [BLANK]', 'options': ['Uncountable (tidak dapat dihitung)', 'Countable (dapat dihitung)'], 'answer': 'Uncountable (tidak dapat dihitung)', 'hint': 'Zat cair tidak dapat dihitung satu per satu.', 'explanation': 'Air (water) adalah uncountable noun.'}, {'q': '2. apple &rarr; [BLANK]', 'options': ['Countable (dapat dihitung)', 'Uncountable (tidak dapat dihitung)'], 'answer': 'Countable (dapat dihitung)', 'hint': 'Buah apel bisa dihitung satu, dua, tiga...', 'explanation': 'Apel (apple) dapat dihitung: one apple, two apples.'}, {'q': '3. money &rarr; [BLANK]', 'options': ['Uncountable (tidak dapat dihitung)', 'Countable (dapat dihitung)'], 'answer': 'Uncountable (tidak dapat dihitung)', 'hint': "Kata 'money' secara gramatikal tidak bisa dihitung (yang dihitung adalah mata uangnya seperti dollars/rupiah).", 'explanation': 'Money adalah kata benda tak terhitung (uncountable noun).'}, {'q': '4. chair &rarr; [BLANK]', 'options': ['Countable (dapat dihitung)', 'Uncountable (tidak dapat dihitung)'], 'answer': 'Countable (dapat dihitung)', 'hint': 'Kursi dapat dihitung.', 'explanation': 'Chair adalah countable noun: one chair, two chairs.'}, {'q': '5. information &rarr; [BLANK]', 'options': ['Uncountable (tidak dapat dihitung)', 'Countable (dapat dihitung)'], 'answer': 'Uncountable (tidak dapat dihitung)', 'hint': 'Information tidak memiliki bentuk jamak -s dalam bahasa Inggris.', 'explanation': 'Information selalu uncountable noun.'}, {'q': '6. bread &rarr; [BLANK]', 'options': ['Uncountable (tidak dapat dihitung)', 'Countable (dapat dihitung)'], 'answer': 'Uncountable (tidak dapat dihitung)', 'hint': 'Roti (bread) dianggap sebagai materi/massa tak terhitung, dihitung per slice atau loaf.', 'explanation': 'Bread dalam bahasa Inggris adalah uncountable noun.'}]}, {'id': 'u13_ex2', 'unitId': 13, 'page': 42, 'title': 'Latihan 2: Penggunaan a, an, dan some', 'instruction': "Lengkapi dengan artikel 'a', 'an' (untuk countable tunggal) atau 'some' (untuk uncountable atau jamak).", 'type': 'fill', 'questions': [{'q': '1. Would you like [BLANK] apple?', 'answer': 'an', 'alternateAnswers': ['An'], 'hint': 'Apple diawali huruf vokal (vowel sound).', 'explanation': "Gunakan 'an' di depan kata yang berbunyi vokal: an apple."}, {'q': '2. Can I have [BLANK] milk with my cereal?', 'answer': 'some', 'alternateAnswers': ['Some'], 'hint': 'Milk adalah kata benda tak terhitung (uncountable).', 'explanation': "Gunakan 'some' untuk uncountable noun: some milk."}, {'q': '3. I made [BLANK] sandwich for lunch.', 'answer': 'a', 'alternateAnswers': ['A'], 'hint': 'Sandwich diawali huruf konsonan.', 'explanation': "Gunakan 'a' di depan kata benda tunggal berbunyi konsonan: a sandwich."}, {'q': '4. She bought [BLANK] fresh bread at the bakery.', 'answer': 'some', 'alternateAnswers': ['Some'], 'hint': 'Bread adalah uncountable noun.', 'explanation': "Gunakan 'some' untuk bread: some bread."}, {'q': '5. There is [BLANK] orange on the table.', 'answer': 'an', 'alternateAnswers': ['An'], 'hint': "Orange diawali vokal 'o'.", 'explanation': "Gunakan 'an' untuk an orange."}, {'q': '6. We need [BLANK] cheese to make the pizza.', 'answer': 'some', 'alternateAnswers': ['Some'], 'hint': 'Cheese adalah uncountable noun.', 'explanation': "Gunakan 'some' untuk cheese."}]}, {'id': 'u13_ex3', 'unitId': 13, 'page': 43, 'title': 'Latihan 3: Penggunaan some dan any', 'instruction': "Pilihlah some atau any: 'some' untuk kalimat positif, tawaran, atau permohonan sopan; 'any' untuk kalimat negatif dan pertanyaan umum.", 'type': 'choice', 'questions': [{'q': '1. There is [BLANK] butter in the fridge.', 'options': ['some', 'any'], 'answer': 'some', 'hint': 'Kalimat berita positif.', 'explanation': "Kalimat positif menggunakan 'some'."}, {'q': '2. Are there [BLANK] eggs left in the carton?', 'options': ['any', 'some'], 'answer': 'any', 'hint': 'Pertanyaan umum.', 'explanation': "Kalimat tanya umum menggunakan 'any'."}, {'q': "3. We don't have [BLANK] sugar to bake the cake.", 'options': ['any', 'some'], 'answer': 'any', 'hint': "Kalimat negatif (don't have).", 'explanation': "Kalimat negatif menggunakan 'any'."}, {'q': '4. Would you like [BLANK] hot chocolate?', 'options': ['some', 'any'], 'answer': 'some', 'hint': 'Tawaran ramah (offer).', 'explanation': "Tawaran (offers) sopan menggunakan 'some'."}, {'q': '5. Can I have [BLANK] water, please?', 'options': ['some', 'any'], 'answer': 'some', 'hint': 'Permohonan sopan (request).', 'explanation': "Permintaan sopan (requests) menggunakan 'some'."}, {'q': "6. He didn't take [BLANK] photos during the concert.", 'options': ['any', 'some'], 'answer': 'any', 'hint': "Kalimat negatif (didn't take).", 'explanation': "Kalimat negatif menggunakan 'any'."}]}, {'id': 'u13_ex4', 'unitId': 13, 'page': 43, 'title': 'Latihan 4: How much vs How many', 'instruction': "Lengkapi pertanyaan dengan 'How much' (untuk uncountable) atau 'How many' (untuk countable jamak).", 'type': 'fill', 'questions': [{'q': '1. [BLANK] students are in your class?', 'answer': 'How many', 'alternateAnswers': ['how many'], 'hint': 'Students adalah countable jamak.', 'explanation': "Kata benda jamak dapat dihitung menggunakan 'How many'."}, {'q': '2. [BLANK] money do you need for the bus?', 'answer': 'How much', 'alternateAnswers': ['how much'], 'hint': 'Money adalah uncountable.', 'explanation': "Kata benda tidak dapat dihitung menggunakan 'How much'."}, {'q': '3. [BLANK] time do we have before the train arrives?', 'answer': 'How much', 'alternateAnswers': ['how much'], 'hint': 'Time (waktu) adalah uncountable.', 'explanation': "Waktu (time) menggunakan 'How much'."}, {'q': '4. [BLANK] apples did you buy at the market?', 'answer': 'How many', 'alternateAnswers': ['how many'], 'hint': 'Apples adalah countable jamak.', 'explanation': "Kata benda apel menggunakan 'How many'."}, {'q': '5. [BLANK] water do you drink every day?', 'answer': 'How much', 'alternateAnswers': ['how much'], 'hint': 'Water adalah zat cair tak terhitung.', 'explanation': "Water menggunakan 'How much'."}, {'q': '6. [BLANK] books have you read this year?', 'answer': 'How many', 'alternateAnswers': ['how many'], 'hint': 'Books adalah countable jamak.', 'explanation': "Books menggunakan 'How many'."}]}, {'id': 'u13_ex5', 'unitId': 13, 'page': 43, 'title': 'Latihan 5: much, many, atau a lot of', 'instruction': 'Pilih kata penentu kuantitas yang paling tepat sesuai kaidah gramatikal.', 'type': 'choice', 'questions': [{'q': '1. There are [BLANK] tourists in the museum today.', 'options': ['a lot of', 'much', 'any'], 'answer': 'a lot of', 'hint': 'Kalimat positif untuk jumlah banyak.', 'explanation': "Dalam kalimat positif, lebih alami menggunakan 'a lot of'."}, {'q': "2. We don't have [BLANK] petrol left in the car.", 'options': ['much', 'many', 'a few'], 'answer': 'much', 'hint': 'Petrol adalah uncountable dalam kalimat negatif.', 'explanation': "Uncountable dalam kalimat negatif menggunakan 'much'."}, {'q': "3. She didn't invite [BLANK] people to her birthday party.", 'options': ['many', 'much', 'little'], 'answer': 'many', 'hint': 'People adalah countable jamak dalam kalimat negatif.', 'explanation': "Countable jamak dalam kalimat negatif menggunakan 'many'."}, {'q': '4. He drinks [BLANK] coffee every morning.', 'options': ['a lot of', 'many', 'any'], 'answer': 'a lot of', 'hint': 'Kalimat afirmatif/positif untuk uncountable.', 'explanation': "Kalimat positif menggunakan 'a lot of'."}]}, {'id': 'u13_ex6', 'unitId': 13, 'page': 44, 'title': 'Latihan 6: a few vs a little', 'instruction': "Lengkapi kalimat dengan 'a few' (beberapa - untuk countable jamak) atau 'a little' (sedikit - untuk uncountable).", 'type': 'fill', 'questions': [{'q': '1. I have [BLANK] friends living in London.', 'answer': 'a few', 'alternateAnswers': ['A few'], 'hint': 'Friends adalah countable jamak.', 'explanation': "Gunakan 'a few' untuk kata benda dapat dihitung jamak."}, {'q': '2. Could you add [BLANK] salt to the soup?', 'answer': 'a little', 'alternateAnswers': ['A little'], 'hint': 'Salt adalah uncountable.', 'explanation': "Gunakan 'a little' untuk kata benda tak terhitung."}, {'q': '3. We still have [BLANK] time before the movie starts.', 'answer': 'a little', 'alternateAnswers': ['A little'], 'hint': 'Time adalah uncountable.', 'explanation': "Gunakan 'a little' untuk time."}, {'q': '4. There are only [BLANK] biscuits left in the tin.', 'answer': 'a few', 'alternateAnswers': ['A few'], 'hint': 'Biscuits adalah countable jamak.', 'explanation': "Gunakan 'a few' untuk biscuits."}, {'q': '5. She speaks [BLANK] Spanish when she travels.', 'answer': 'a little', 'alternateAnswers': ['A little'], 'hint': 'Spanish (kemampuan bahasa) adalah uncountable.', 'explanation': "Gunakan 'a little' untuk bahasa."}, {'q': '6. He bought [BLANK] magazines to read on the train.', 'answer': 'a few', 'alternateAnswers': ['A few'], 'hint': 'Magazines adalah countable jamak.', 'explanation': "Gunakan 'a few' untuk magazines."}]}, {'id': 'u13_ex7', 'unitId': 13, 'page': 44, 'title': 'Latihan 7: Dialog Berbelanja di Toko Kelontong', 'instruction': 'Lengkapi percakapan berbelanja berikut dengan kuantifier yang tepat: some, any, much, many, a few, a little.', 'type': 'fill', 'questions': [{'q': '1. Shopkeeper: Good morning! How [BLANK] apples would you like?', 'answer': 'many', 'alternateAnswers': ['Many'], 'hint': 'Menanyakan jumlah apel (countable).', 'explanation': 'How many apples.'}, {'q': "2. Customer: I'd like [BLANK] red apples, please. About four.", 'answer': 'a few', 'alternateAnswers': ['some', 'A few', 'Some'], 'hint': 'Jumlah sedikit (sekitar empat).', 'explanation': "'a few' atau 'some' red apples."}, {'q': '3. Customer: Do you have [BLANK] fresh orange juice?', 'answer': 'any', 'alternateAnswers': ['Any'], 'hint': 'Pertanyaan apakah tersedia.', 'explanation': "Pertanyaan umum menggunakan 'any'."}, {'q': '4. Shopkeeper: Yes, we do. How [BLANK] bottles do you want?', 'answer': 'many', 'alternateAnswers': ['Many'], 'hint': 'Bottles adalah countable jamak.', 'explanation': 'How many bottles.'}, {'q': '5. Customer: Just one bottle. And how [BLANK] is that in total?', 'answer': 'much', 'alternateAnswers': ['Much'], 'hint': 'Menanyakan harga total uang.', 'explanation': 'How much is that in total?'}]}, {'id': 'u13_ex8', 'unitId': 13, 'page': 44, 'title': 'Latihan 8: Mengoreksi Kesalahan Penggunaan Kuantifier', 'instruction': 'Pilihlah kalimat yang benar untuk mengoreksi kesalahan pada kalimat-kalimat berikut.', 'type': 'choice', 'questions': [{'q': "1. Salah: 'I don't have many money.' &rarr; Benar: [BLANK]", 'options': ["I don't have much money.", "I don't have a few money.", 'I have many money.', "I don't have some money."], 'answer': "I don't have much money.", 'hint': 'Money adalah uncountable, gunakan much.', 'explanation': "Money tak terhitung, sehingga bentuk negatifnya menggunakan 'much money'."}, {'q': "2. Salah: 'Can I have any water, please?' &rarr; Benar: [BLANK]", 'options': ['Can I have some water, please?', 'Can I have many water, please?', 'Can I have a few water, please?', 'Can I have an water, please?'], 'answer': 'Can I have some water, please?', 'hint': 'Permintaan sopan (request) menggunakan some.', 'explanation': "Dalam permohonan sopan, gunakan 'some water'."}, {'q': "3. Salah: 'There are much chairs in the room.' &rarr; Benar: [BLANK]", 'options': ['There are many chairs in the room.', 'There are a little chairs in the room.', 'There is much chairs in the room.', 'There are any chairs in the room.'], 'answer': 'There are many chairs in the room.', 'hint': 'Chairs adalah countable jamak.', 'explanation': "Kata benda jamak yang dapat dihitung memakai 'many chairs' atau 'a lot of chairs'."}, {'q': "4. Salah: 'She put a few sugar in her tea.' &rarr; Benar: [BLANK]", 'options': ['She put a little sugar in her tea.', 'She put many sugar in her tea.', 'She put a sugar in her tea.', 'She put few sugar in her tea.'], 'answer': 'She put a little sugar in her tea.', 'hint': 'Sugar adalah uncountable.', 'explanation': "Gula tak terhitung memakai 'a little sugar'."}]}]

U14_EXERCISES = [{'id': 'u14_ex1', 'unitId': 14, 'page': 45, 'title': 'Latihan 1: Fungsi Kata Ganti Penghubung (Relative Pronouns)', 'instruction': 'Pasangkan kata ganti penghubung (relative pronouns) dengan fungsinya yang tepat.', 'type': 'choice', 'questions': [{'q': "1. 'who' digunakan untuk merujuk pada: [BLANK]", 'options': ['Orang (people)', 'Benda atau binatang (things or animals)', 'Tempat (places)', 'Kepemilikan (possession)'], 'answer': 'Orang (people)', 'hint': "'who' selalu merujuk pada manusia/orang.", 'explanation': "'who' digunakan untuk people (orang)."}, {'q': "2. 'which' digunakan untuk merujuk pada: [BLANK]", 'options': ['Benda atau binatang (things or animals)', 'Orang (people)', 'Tempat (places)', 'Waktu (time)'], 'answer': 'Benda atau binatang (things or animals)', 'hint': "'which' merujuk pada benda mati atau hewan.", 'explanation': "'which' digunakan untuk things and animals."}, {'q': "3. 'where' digunakan untuk merujuk pada: [BLANK]", 'options': ['Tempat (places)', 'Orang (people)', 'Kepemilikan (possession)', 'Alasan (reasons)'], 'answer': 'Tempat (places)', 'hint': "'where' berkaitan dengan lokasi atau tempat.", 'explanation': "'where' digunakan untuk places."}, {'q': "4. 'whose' digunakan untuk merujuk pada: [BLANK]", 'options': ['Kepemilikan (possession)', 'Orang (people)', 'Benda (things)', 'Tempat (places)'], 'answer': 'Kepemilikan (possession)', 'hint': "'whose' menunjukkan milik siapa.", 'explanation': "'whose' digunakan untuk kepunyaan / possession."}]}, {'id': 'u14_ex2', 'unitId': 14, 'page': 45, 'title': 'Latihan 2: Melengkapi dengan who atau which', 'instruction': "Lengkapi kalimat dengan 'who' (untuk manusia) atau 'which' (untuk benda/hewan).", 'type': 'fill', 'questions': [{'q': '1. A teacher is a person [BLANK] helps students learn.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'A person adalah manusia.', 'explanation': "Person adalah orang &rarr; gunakan 'who'."}, {'q': '2. A telescope is an instrument [BLANK] looks at distant stars.', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'An instrument adalah benda alat.', 'explanation': "Instrument adalah benda &rarr; gunakan 'which'."}, {'q': '3. The woman [BLANK] lives next door is very kind.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'The woman adalah orang.', 'explanation': "Woman adalah manusia &rarr; gunakan 'who'."}, {'q': '4. The novel [BLANK] I bought yesterday is thrilling.', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'The novel adalah buku/benda.', 'explanation': "Novel adalah benda &rarr; gunakan 'which'."}, {'q': '5. The doctor [BLANK] treated me was very experienced.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'Doctor adalah orang.', 'explanation': "Doctor adalah orang &rarr; gunakan 'who'."}, {'q': '6. A dolphin is an animal [BLANK] is very intelligent.', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'Animal adalah binatang.', 'explanation': "Animal merujuk ke hewan &rarr; gunakan 'which'."}]}, {'id': 'u14_ex3', 'unitId': 14, 'page': 46, 'title': 'Latihan 3: who, which, atau where', 'instruction': 'Pilihlah who (orang), which (benda), atau where (tempat) untuk melengkapi kalimat.', 'type': 'choice', 'questions': [{'q': '1. The restaurant [BLANK] we had dinner last night was fantastic.', 'options': ['where', 'which', 'who'], 'answer': 'where', 'hint': 'Restaurant adalah lokasi tempat kita makan.', 'explanation': "Menunjukkan lokasi terjadinya kegiatan &rarr; 'where'."}, {'q': '2. The boy [BLANK] won the swimming competition is my cousin.', 'options': ['who', 'which', 'where'], 'answer': 'who', 'hint': 'The boy adalah orang.', 'explanation': "Merujuk ke manusia &rarr; 'who'."}, {'q': '3. The laptop [BLANK] is on the table belongs to Mark.', 'options': ['which', 'who', 'where'], 'answer': 'which', 'hint': 'The laptop adalah benda.', 'explanation': "Merujuk ke benda &rarr; 'which'."}, {'q': '4. This is the park [BLANK] we used to play football every Sunday.', 'options': ['where', 'which', 'who'], 'answer': 'where', 'hint': 'The park adalah lokasi tempat bermain.', 'explanation': "Merujuk ke lokasi kegiatan &rarr; 'where'."}, {'q': '5. The shoes [BLANK] I bought online are too small.', 'options': ['which', 'who', 'where'], 'answer': 'which', 'hint': 'The shoes adalah benda.', 'explanation': "Merujuk ke benda &rarr; 'which'."}, {'q': '6. I spoke to the manager [BLANK] was very helpful.', 'options': ['who', 'which', 'where'], 'answer': 'who', 'hint': 'The manager adalah orang.', 'explanation': "Merujuk ke orang &rarr; 'who'."}]}, {'id': 'u14_ex4', 'unitId': 14, 'page': 46, 'title': "Latihan 4: Membedakan whose dan who's", 'instruction': "Lengkapi kalimat dengan 'whose' (kata ganti kepemilikan) atau 'who's' (singkatan dari who is / who has).", 'type': 'fill', 'questions': [{'q': "1. That's the girl [BLANK] dog was lost in the woods.", 'answer': 'whose', 'alternateAnswers': ['Whose'], 'hint': 'Menunjukkan pemilik anjing tersebut.', 'explanation': "Kepemilikan anjing milik anak perempuan: 'whose dog'."}, {'q': '2. Do you know [BLANK] knocking at the door?', 'answer': "who's", 'alternateAnswers': ['who is', "Who's"], 'hint': "Singkatan dari 'who is'.", 'explanation': "'who's' = who is knocking."}, {'q': '3. The architect [BLANK] design won the award is very proud.', 'answer': 'whose', 'alternateAnswers': ['Whose'], 'hint': 'Desain milik sang arsitek.', 'explanation': "Kepemilikan karya desain: 'whose design'."}, {'q': '4. [BLANK] that boy standing next to Sarah?', 'answer': "Who's", 'alternateAnswers': ["who's", 'Who is'], 'hint': "Singkatan dari 'Who is that boy'.", 'explanation': "'Who's' = Who is that boy?"}, {'q': '5. We met a woman [BLANK] car had broken down on the highway.', 'answer': 'whose', 'alternateAnswers': ['Whose'], 'hint': 'Mobil milik wanita tersebut.', 'explanation': "Kepemilikan mobil: 'whose car'."}]}, {'id': 'u14_ex5', 'unitId': 14, 'page': 46, 'title': 'Latihan 5: Menggabungkan Dua Kalimat dengan Relative Pronoun', 'instruction': 'Gabungkan dua kalimat berikut menjadi satu kalimat kompleks menggunakan kata ganti penghubung (who, which, whose, where).', 'type': 'fill', 'questions': [{'q': '1. I met a girl. She speaks four languages. &rarr; [BLANK]', 'answer': 'I met a girl who speaks four languages.', 'alternateAnswers': ['i met a girl who speaks four languages.', 'I met a girl that speaks four languages.'], 'hint': "Gunakan 'who' menggantikan 'She'.", 'explanation': 'I met a girl who speaks four languages.'}, {'q': '2. Here is the book. You lent it to me. &rarr; [BLANK]', 'answer': 'Here is the book which you lent to me.', 'alternateAnswers': ['here is the book which you lent to me.', 'Here is the book that you lent to me.', 'Here is the book you lent to me.'], 'hint': "Gunakan 'which' atau 'that' menggantikan 'it'.", 'explanation': 'Here is the book which you lent to me.'}, {'q': '3. That is the hospital. My mother works there. &rarr; [BLANK]', 'answer': 'That is the hospital where my mother works.', 'alternateAnswers': ['that is the hospital where my mother works.', 'That is the hospital where my mother works'], 'hint': "Gunakan 'where' menggantikan 'there'.", 'explanation': 'That is the hospital where my mother works.'}, {'q': "4. That's the boy. His brother won the gold medal. &rarr; [BLANK]", 'answer': "That's the boy whose brother won the gold medal.", 'alternateAnswers': ["that's the boy whose brother won the gold medal.", 'That is the boy whose brother won the gold medal.'], 'hint': "Gunakan 'whose' menggantikan 'His'.", 'explanation': "That's the boy whose brother won the gold medal."}]}, {'id': 'u14_ex6', 'unitId': 14, 'page': 46, 'title': 'Latihan 6: Menghilangkan Kata Ganti Penghubung (Omitting Relative Pronouns)', 'instruction': 'Tentukan apakah kata ganti penghubung (who / which / that) pada kalimat berikut DAPAT dihilangkan (can be omitted - sebagai objek) atau TIDAK dapat dihilangkan (cannot be omitted - sebagai subjek).', 'type': 'choice', 'questions': [{'q': '1. The movie which we watched last night was thrilling.', 'options': ['DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa', 'TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa'], 'answer': 'DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa', 'hint': "Subjek klausa berikutnya adalah 'we', jadi 'which' adalah objek.", 'explanation': "Bisa dikatakan 'The movie we watched last night was thrilling.' sehingga dapat dihilangkan."}, {'q': '2. The man who repaired our roof was very polite.', 'options': ['TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa', 'DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa'], 'answer': 'TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa', 'hint': "'who' langsung diikuti kata kerja 'repaired', artinya 'who' adalah subjek.", 'explanation': "'who' bertindak sebagai subjek klausa relatif sehingga TIDAK boleh dihilangkan."}, {'q': "3. The email that you sent me didn't arrive.", 'options': ['DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa', 'TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa'], 'answer': 'DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa', 'hint': "'you' adalah subjek dari klausa 'you sent me'.", 'explanation': "Bisa disederhanakan: 'The email you sent me didn't arrive.'"}, {'q': '4. The students who study hard will pass the exam.', 'options': ['TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa', 'DAPAT dihilangkan (Can be omitted) - karena merupakan objek klausa'], 'answer': 'TIDAK dapat dihilangkan (Cannot be omitted) - karena merupakan subjek klausa', 'hint': "'who' adalah pelaku kata kerja 'study'.", 'explanation': "'who' sebagai subjek klausa relatif tidak boleh dihilangkan."}]}, {'id': 'u14_ex7', 'unitId': 14, 'page': 47, 'title': 'Latihan 7: Pilihan Ganda Relative Pronouns', 'instruction': 'Pilihlah kata ganti penghubung yang paling tepat untuk melengkapi setiap kalimat berikut.', 'type': 'choice', 'questions': [{'q': '1. An author is someone [BLANK] writes books.', 'options': ['who', 'which', 'where', 'whose'], 'answer': 'who', 'hint': 'Author adalah manusia pembuat buku.', 'explanation': "'who' digunakan untuk subjek orang."}, {'q': '2. The cafe [BLANK] they serve the best hot chocolate is just around the corner.', 'options': ['where', 'which', 'who', 'whose'], 'answer': 'where', 'hint': 'Cafe adalah tempat.', 'explanation': "'where' digunakan untuk lokasi tempat."}, {'q': '3. Is this the camera [BLANK] you lost last week?', 'options': ['which', 'who', 'where', 'whose'], 'answer': 'which', 'hint': 'Camera adalah benda.', 'explanation': "'which' digunakan untuk benda."}, {'q': '4. We met a neighbour [BLANK] son is studying in Oxford.', 'options': ['whose', 'who', 'which', 'where'], 'answer': 'whose', 'hint': 'Anak laki-laki dari sang tetangga.', 'explanation': "'whose' menyatakan hubungan keluarga / kepemilikan."}]}, {'id': 'u14_ex8', 'unitId': 14, 'page': 47, 'title': 'Latihan 8: Relative Clauses Pronunciation (Audio TR 20)', 'instruction': 'Dengarkan audio TR 20 dan lengkapi kata hubung relatif yang diucapkan pada setiap kalimat berikut.', 'type': 'fill', 'audioTrack': 'TR 20', 'questions': [{'q': '1. The eggs [BLANK] I bought yesterday are bad.', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'Benda: the eggs.', 'explanation': "Audio TR 20 nomor 1: 'The eggs which I bought yesterday are bad.'"}, {'q': '2. The boy [BLANK] broke the window will be punished.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'Orang: the boy.', 'explanation': "Audio TR 20 nomor 2: 'The boy who broke the window will be punished.'"}, {'q': '3. The hairdresser [BLANK] cut your hair did a good job.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'Orang: the hairdresser.', 'explanation': "Audio TR 20 nomor 3: 'The hairdresser who cut your hair did a good job.'"}, {'q': '4. Is the book [BLANK] is on the table mine?', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'Benda: the book.', 'explanation': "Audio TR 20 nomor 4: 'Is the book which is on the table mine?'"}, {'q': '5. This is the shop [BLANK] I go to buy my clothes.', 'answer': 'where', 'alternateAnswers': ['Where'], 'hint': 'Tempat: the shop.', 'explanation': "Audio TR 20 nomor 5: 'This is the shop where I go to buy my clothes.'"}, {'q': '6. The boy [BLANK] is sitting at the desk is my brother.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'Orang: the boy.', 'explanation': "Audio TR 20 nomor 6: 'The boy who is sitting at the desk is my brother.'"}]}, {'id': 'u14_ex9', 'unitId': 14, 'page': 47, 'title': 'Latihan 9: Melengkapi Kalimat Definisi dengan who, which, atau where', 'instruction': 'Lengkapi kalimat definisi kosakata berikut dengan who, which, atau where.', 'type': 'fill', 'questions': [{'q': '1. A library is a place [BLANK] you can borrow books.', 'answer': 'where', 'alternateAnswers': ['Where'], 'hint': 'A place adalah tempat.', 'explanation': "Tempat meminjam buku &rarr; 'where'."}, {'q': '2. A pilot is a person [BLANK] flies aeroplanes.', 'answer': 'who', 'alternateAnswers': ['that', 'Who'], 'hint': 'A person adalah orang.', 'explanation': "Orang penerbang pesawat &rarr; 'who'."}, {'q': '3. A thermometer is an instrument [BLANK] measures temperature.', 'answer': 'which', 'alternateAnswers': ['that', 'Which'], 'hint': 'An instrument adalah alat ukur (benda).', 'explanation': "Alat pengukur &rarr; 'which'."}, {'q': '4. A bakery is a shop [BLANK] you can buy fresh bread and cakes.', 'answer': 'where', 'alternateAnswers': ['Where'], 'hint': 'A shop adalah tempat berbelanja.', 'explanation': "Toko roti &rarr; 'where'."}]}, {'id': 'u14_ex10', 'unitId': 14, 'page': 47, 'title': 'Latihan 10: Mengoreksi Kesalahan Relative Pronoun', 'instruction': 'Pilihlah perbaikan yang tepat untuk mengoreksi kata ganti relatif yang salah dalam kalimat.', 'type': 'choice', 'questions': [{'q': "1. Salah: 'The person which called you didn't leave a message.' &rarr; Benar: [BLANK]", 'options': ["The person who called you didn't leave a message.", "The person where called you didn't leave a message.", "The person whose called you didn't leave a message.", "The person whom called you didn't leave a message."], 'answer': "The person who called you didn't leave a message.", 'hint': 'Person adalah orang, tidak boleh memakai which.', 'explanation': "Untuk merujuk ke orang (person), gunakan 'who'."}, {'q': "2. Salah: 'I love the city which I was born.' &rarr; Benar: [BLANK]", 'options': ['I love the city where I was born.', 'I love the city who I was born.', 'I love the city whose I was born.', 'I love the city that I was born in where.'], 'answer': 'I love the city where I was born.', 'hint': 'Kota tempat dilahirkan membutuhkan kata keterangan tempat.', 'explanation': "Tempat dilahirkan: 'the city where I was born'."}, {'q': "3. Salah: 'He is the man who's car was stolen yesterday.' &rarr; Benar: [BLANK]", 'options': ['He is the man whose car was stolen yesterday.', 'He is the man which car was stolen yesterday.', 'He is the man where car was stolen yesterday.', 'He is the man whom car was stolen yesterday.'], 'answer': 'He is the man whose car was stolen yesterday.', 'hint': 'Menyatakan kepemilikan mobil (bukan who is).', 'explanation': "Kepemilikan mobil pria tersebut menggunakan 'whose car'."}]}]

U15_EXERCISES = [{'id': 'u15_ex1', 'unitId': 15, 'page': 48, 'title': 'Latihan 1: Pola Verb + Gerund (-ing) vs Verb + Infinitive (to)', 'instruction': 'Kelompokkan kata kerja berikut berdasarkan pola setelahnya: diikuti Gerund (-ing) atau diikuti to-Infinitive.', 'type': 'choice', 'questions': [{'q': "1. Kata kerja 'enjoy' selalu diikuti oleh: [BLANK]", 'options': ['Gerund (V-ing)', 'to-Infinitive (to + V1)', 'Bare infinitive (V1)'], 'answer': 'Gerund (V-ing)', 'hint': 'Contoh: enjoy playing tennis.', 'explanation': "'enjoy' selalu diikuti bentuk gerund (-ing)."}, {'q': "2. Kata kerja 'decide' selalu diikuti oleh: [BLANK]", 'options': ['to-Infinitive (to + V1)', 'Gerund (V-ing)', 'Kata sifat'], 'answer': 'to-Infinitive (to + V1)', 'hint': 'Contoh: decide to buy a new car.', 'explanation': "'decide' diikuti bentuk to-infinitive."}, {'q': "3. Kata kerja 'mind' (dalam 'don't mind / would you mind') diikuti oleh: [BLANK]", 'options': ['Gerund (V-ing)', 'to-Infinitive (to + V1)', 'Past simple'], 'answer': 'Gerund (V-ing)', 'hint': "Contoh: I don't mind waiting.", 'explanation': "'mind' diikuti oleh gerund (-ing)."}, {'q': "4. Kata kerja 'promise' selalu diikuti oleh: [BLANK]", 'options': ['to-Infinitive (to + V1)', 'Gerund (V-ing)', 'Bare infinitive'], 'answer': 'to-Infinitive (to + V1)', 'hint': 'Contoh: promise to help someone.', 'explanation': "'promise' diikuti oleh to-infinitive."}, {'q': "5. Kata kerja 'avoid' selalu diikuti oleh: [BLANK]", 'options': ['Gerund (V-ing)', 'to-Infinitive (to + V1)', 'Bare infinitive'], 'answer': 'Gerund (V-ing)', 'hint': 'Contoh: avoid making mistakes.', 'explanation': "'avoid' diikuti oleh gerund (-ing)."}, {'q': "6. Kata kerja 'hope' selalu diikuti oleh: [BLANK]", 'options': ['to-Infinitive (to + V1)', 'Gerund (V-ing)', 'Preposition of place'], 'answer': 'to-Infinitive (to + V1)', 'hint': 'Contoh: hope to pass the test.', 'explanation': "'hope' diikuti oleh to-infinitive."}]}, {'id': 'u15_ex2', 'unitId': 15, 'page': 48, 'title': 'Latihan 2: Melengkapi Kalimat dengan Gerund (-ing)', 'instruction': 'Ubah kata kerja dalam tanda kurung menjadi bentuk Gerund (-ing) untuk melengkapi kalimat.', 'type': 'fill', 'questions': [{'q': '1. She avoids [BLANK] (eat) junk food because she wants to stay healthy.', 'answer': 'eating', 'alternateAnswers': ['Eating'], 'hint': 'eat + ing.', 'explanation': 'Avoid eating junk food.'}, {'q': '2. Do you fancy [BLANK] (go) to the cinema this evening?', 'answer': 'going', 'alternateAnswers': ['Going'], 'hint': 'go + ing.', 'explanation': 'Fancy going to the cinema.'}, {'q': '3. He admitted [BLANK] (break) the window by accident.', 'answer': 'breaking', 'alternateAnswers': ['Breaking'], 'hint': 'break + ing.', 'explanation': 'Admitted breaking the window.'}, {'q': "4. I can't imagine [BLANK] (live) in a freezing cold country.", 'answer': 'living', 'alternateAnswers': ['Living'], 'hint': "live huruf 'e' dihilangkan lalu tambah ing.", 'explanation': 'Imagine living in a cold country.'}, {'q': '5. We finished [BLANK] (paint) the bedroom walls yesterday.', 'answer': 'painting', 'alternateAnswers': ['Painting'], 'hint': 'paint + ing.', 'explanation': 'Finished painting the walls.'}]}, {'id': 'u15_ex3', 'unitId': 15, 'page': 49, 'title': 'Latihan 3: Melengkapi Kalimat dengan to-Infinitive', 'instruction': 'Lengkapi kalimat dengan to-infinitive (to + kata kerja) dari kata kerja dalam kurung.', 'type': 'fill', 'questions': [{'q': '1. They agreed [BLANK] (meet) us at the station at six.', 'answer': 'to meet', 'alternateAnswers': ['To meet'], 'hint': 'to + meet.', 'explanation': 'Agreed to meet us.'}, {'q': '2. She offered [BLANK] (carry) the heavy bags for her grandmother.', 'answer': 'to carry', 'alternateAnswers': ['To carry'], 'hint': 'to + carry.', 'explanation': 'Offered to carry the bags.'}, {'q': "3. Don't forget [BLANK] (lock) the front door before you leave.", 'answer': 'to lock', 'alternateAnswers': ['To lock'], 'hint': 'to + lock.', 'explanation': "Don't forget to lock the door."}, {'q': '4. He hopes [BLANK] (study) engineering at university.', 'answer': 'to study', 'alternateAnswers': ['To study'], 'hint': 'to + study.', 'explanation': 'Hopes to study engineering.'}, {'q': '5. We managed [BLANK] (catch) the last bus home.', 'answer': 'to catch', 'alternateAnswers': ['To catch'], 'hint': 'to + catch.', 'explanation': 'Managed to catch the bus.'}]}, {'id': 'u15_ex4', 'unitId': 15, 'page': 49, 'title': 'Latihan 4: Memilih antara Gerund (-ing) atau to-Infinitive', 'instruction': 'Pilihlah bentuk kata kerja yang benar (-ing atau to-infinitive) sesuai kata kerja utamanya.', 'type': 'choice', 'questions': [{'q': '1. I refused [BLANK] his question because it was too personal.', 'options': ['to answer', 'answering', 'answer'], 'answer': 'to answer', 'hint': "'refuse' berpasangan dengan to-infinitive.", 'explanation': 'Refuse to answer.'}, {'q': '2. She suggested [BLANK] a picnic in the park.', 'options': ['having', 'to have', 'have'], 'answer': 'having', 'hint': "'suggest' diikuti gerund.", 'explanation': 'Suggest having a picnic.'}, {'q': '3. They decided [BLANK] their holiday in Portugal.', 'options': ['to spend', 'spending', 'spend'], 'answer': 'to spend', 'hint': "'decide' diikuti to-infinitive.", 'explanation': 'Decided to spend.'}, {'q': '4. I really enjoy [BLANK] novels on rainy afternoons.', 'options': ['reading', 'to read', 'read'], 'answer': 'reading', 'hint': "'enjoy' diikuti gerund.", 'explanation': 'Enjoy reading novels.'}, {'q': '5. He promised [BLANK] me as soon as he arrived.', 'options': ['to call', 'calling', 'call'], 'answer': 'to call', 'hint': "'promise' diikuti to-infinitive.", 'explanation': 'Promised to call.'}]}, {'id': 'u15_ex5', 'unitId': 15, 'page': 49, 'title': 'Latihan 5: Verb + -ing or Infinitive (Audio TR 21)', 'instruction': 'Dengarkan rekaman audio TR 21 dan tentukan apakah kalimat yang diperdengarkan menggunakan bentuk gerund (-ing) atau to-infinitive.', 'type': 'choice', 'audioTrack': 'TR 21', 'questions': [{'q': "1. Kalimat 1: 'I liked going swimming.' &rarr; Pola yang digunakan:", 'options': ['Gerund (-ing): going swimming', 'to-Infinitive: to swim'], 'answer': 'Gerund (-ing): going swimming', 'hint': "Dengarkan kata setelah liked: 'going'.", 'explanation': "Audio TR 21 nomor 1: 'I liked going swimming.' (Gerund)"}, {'q': "2. Kalimat 2: 'I learnt to speak English when I was a child.' &rarr; Pola yang digunakan:", 'options': ['to-Infinitive: to speak', 'Gerund (-ing): speaking'], 'answer': 'to-Infinitive: to speak', 'hint': "Dengarkan kata setelah learnt: 'to speak'.", 'explanation': "Audio TR 21 nomor 2: 'I learnt to speak English...' (to-Infinitive)"}, {'q': "3. Kalimat 3: 'They didn't want to go.' &rarr; Pola yang digunakan:", 'options': ['to-Infinitive: to go', 'Gerund (-ing): going'], 'answer': 'to-Infinitive: to go', 'hint': "Dengarkan kata setelah want: 'to go'.", 'explanation': "Audio TR 21 nomor 3: 'They didn't want to go.' (to-Infinitive)"}, {'q': "4. Kalimat 4: 'They were allowed to stay late.' &rarr; Pola yang digunakan:", 'options': ['to-Infinitive: to stay', 'Gerund (-ing): staying'], 'answer': 'to-Infinitive: to stay', 'hint': "Dengarkan kata setelah allowed: 'to stay'.", 'explanation': "Audio TR 21 nomor 4: 'They were allowed to stay late.' (to-Infinitive)"}, {'q': "5. Kalimat 6: 'I love buying new clothes.' &rarr; Pola yang digunakan:", 'options': ['Gerund (-ing): buying', 'to-Infinitive: to buy'], 'answer': 'Gerund (-ing): buying', 'hint': "Dengarkan kata setelah love: 'buying'.", 'explanation': "Audio TR 21 nomor 6: 'I love buying new clothes.' (Gerund)"}]}, {'id': 'u15_ex6', 'unitId': 15, 'page': 50, 'title': 'Latihan 6: Rencana Akhir Pekan Andy & Angela (Audio TR 22)', 'instruction': 'Dengarkan dialog antara Andy dan Angela mengenai rencana akhir pekan mereka pada audio TR 22, lalu jawablah pertanyaan berikut.', 'type': 'choice', 'audioTrack': 'TR 22', 'questions': [{'q': "1. Why can't Angela have dinner with Andy tonight?", 'options': ['She has a Russian class.', 'She has to study Maths.', 'She is going to the doctor.', 'She has to clean her room.'], 'answer': 'She has a Russian class.', 'hint': 'Angela menyebutkan ada les bahasa malam ini.', 'explanation': "Angela: 'I'd love to but I have a Russian class.'"}, {'q': '2. What does Andy want to do on Saturday evening?', 'options': ['Go to the cinema, because he loves watching films.', 'Go to an Italian restaurant.', 'Play football in the park.', 'Stay at home and play video games.'], 'answer': 'Go to the cinema, because he loves watching films.', 'hint': 'Andy sangat suka menonton film.', 'explanation': "Andy: 'I want to go to the cinema. You know, I love watching films.'"}, {'q': '3. Which film show time was Andy thinking of going to?', 'options': ["The eight o'clock show.", "The five o'clock show.", "The ten o'clock show.", 'The afternoon matinee.'], 'answer': "The eight o'clock show.", 'hint': 'Dengarkan jam tayang yang diusulkan Andy.', 'explanation': "Andy: 'I was thinking of going to the eight o'clock show.'"}, {'q': "4. Why can't Andy pick Angela up at her house by car?", 'options': ['He promised to lend his car to his brother on Saturday.', 'His car is broken.', "He doesn't have a driving licence.", "He doesn't know where she lives."], 'answer': 'He promised to lend his car to his brother on Saturday.', 'hint': 'Andy sudah berjanji meminjamkan mobil ke saudaranya.', 'explanation': "Andy: 'I promised to lend my car to my brother Saturday.'"}, {'q': '5. What time does Andy expect to be ready and meet Angela?', 'options': ['By half past seven (7:30).', "At eight o'clock (8:00).", "At seven o'clock (7:00).", 'At six-thirty (6:30).'], 'answer': 'By half past seven (7:30).', 'hint': 'Dengarkan jam pertemuan yang disepakati.', 'explanation': "Andy: 'I expect to be ready by half past seven.' Angela: 'Seven-thirty is fine.'"}]}, {'id': 'u15_ex7', 'unitId': 15, 'page': 50, 'title': 'Latihan 7: Melengkapi Kalimat Campuran (-ing atau to-Infinitive)', 'instruction': 'Lengkapi kalimat dengan bentuk kata kerja yang benar di dalam tanda kurung (apakah memakai -ing atau to + infinitive).', 'type': 'fill', 'questions': [{'q': '1. I look forward to [BLANK] (see) you next week.', 'answer': 'seeing', 'alternateAnswers': ['Seeing'], 'hint': "'look forward to' diikuti bentuk gerund (-ing).", 'explanation': 'Look forward to seeing you.'}, {'q': '2. She refused [BLANK] (tell) him the secret.', 'answer': 'to tell', 'alternateAnswers': ['To tell'], 'hint': 'refuse + to-infinitive.', 'explanation': 'Refused to tell him.'}, {'q': "3. Would you mind [BLANK] (open) the window? It's stuffy.", 'answer': 'opening', 'alternateAnswers': ['Opening'], 'hint': 'would you mind + -ing.', 'explanation': 'Would you mind opening.'}, {'q': '4. We arranged [BLANK] (meet) at the cafe at five.', 'answer': 'to meet', 'alternateAnswers': ['To meet'], 'hint': 'arrange + to-infinitive.', 'explanation': 'Arranged to meet.'}, {'q': '5. He gave up [BLANK] (smoke) two years ago.', 'answer': 'smoking', 'alternateAnswers': ['Smoking'], 'hint': 'give up (phrasal verb) + -ing.', 'explanation': 'Gave up smoking.'}]}, {'id': 'u15_ex8', 'unitId': 15, 'page': 50, 'title': 'Latihan 8: Menjodohkan Belahan Kalimat (Sentence Matching)', 'instruction': 'Pasangkan klausa awal (1-4) dengan kelanjutan klausa yang sesuai (a-d).', 'type': 'choice', 'questions': [{'q': '1. She loves &rarr; [BLANK]', 'options': ['buying new clothes at weekends.', 'to help her with the chores.', 'to lock the front door.', 'to be ready by seven.'], 'answer': 'buying new clothes at weekends.', 'hint': 'Kegemaran berbelanja baju.', 'explanation': 'She loves buying new clothes.'}, {'q': "2. Don't forget &rarr; [BLANK]", 'options': ['to lock the front door.', 'buying new clothes at weekends.', 'to be ready by seven.', 'eating fast food.'], 'answer': 'to lock the front door.', 'hint': 'Pengingat untuk mengunci pintu.', 'explanation': "Don't forget to lock the door."}, {'q': '3. He promised &rarr; [BLANK]', 'options': ['to help her with the chores.', 'buying new clothes at weekends.', 'living in a cold country.', 'avoiding traffic.'], 'answer': 'to help her with the chores.', 'hint': 'Janji untuk membantu pekerjaan rumah.', 'explanation': 'He promised to help her with the chores.'}, {'q': '4. We expect &rarr; [BLANK]', 'options': ["to be ready by seven o'clock.", 'buying new shoes.', 'going swimming tomorrow.', 'swimming across the river.'], 'answer': "to be ready by seven o'clock.", 'hint': 'Harapan untuk siap jam tujuh.', 'explanation': "We expect to be ready by seven o'clock."}]}, {'id': 'u15_ex9', 'unitId': 15, 'page': 50, 'title': 'Latihan 9: Preferensi dan Minat Pribadi', 'instruction': 'Pilihlah kalimat yang paling tepat secara gramatikal untuk mengungkapkan kesukaan dan rencana.', 'type': 'choice', 'questions': [{'q': '1. Ungkapan yang benar untuk hobi berenang:', 'options': ['I enjoy swimming in the sea during summer.', 'I enjoy to swim in the sea.', 'I enjoy swim in the sea.'], 'answer': 'I enjoy swimming in the sea during summer.', 'hint': "'enjoy' membutuhkan bentuk -ing.", 'explanation': "'enjoy' diikuti gerund: 'enjoy swimming'."}, {'q': '2. Ungkapan yang benar untuk rencana belajar ke luar negeri:', 'options': ['I plan to study abroad next year.', 'I plan studying abroad next year.', 'I plan study abroad next year.'], 'answer': 'I plan to study abroad next year.', 'hint': "'plan' berpasangan dengan to-infinitive.", 'explanation': "'plan' diikuti to-infinitive: 'plan to study'."}]}, {'id': 'u15_ex10', 'unitId': 15, 'page': 50, 'title': 'Latihan 10: Mengoreksi Kesalahan Gerund dan Infinitive', 'instruction': 'Pilihlah kalimat pembetulan yang benar dari kesalahan tata bahasa berikut.', 'type': 'choice', 'questions': [{'q': "1. Salah: 'I enjoy to play football with my friends.' &rarr; Benar: [BLANK]", 'options': ['I enjoy playing football with my friends.', 'I enjoy play football with my friends.', 'I enjoy played football with my friends.'], 'answer': 'I enjoy playing football with my friends.', 'hint': 'Enjoy + V-ing.', 'explanation': "Setelah kata kerja 'enjoy' harus menggunakan gerund: 'playing'."}, {'q': "2. Salah: 'She decided studying French next term.' &rarr; Benar: [BLANK]", 'options': ['She decided to study French next term.', 'She decided study French next term.', 'She decided for study French next term.'], 'answer': 'She decided to study French next term.', 'hint': 'Decide + to-infinitive.', 'explanation': "Setelah 'decide' harus memakai to-infinitive: 'to study'."}, {'q': "3. Salah: 'We avoided to make noise in the library.' &rarr; Benar: [BLANK]", 'options': ['We avoided making noise in the library.', 'We avoided make noise in the library.', 'We avoided of making noise in the library.'], 'answer': 'We avoided making noise in the library.', 'hint': 'Avoid + V-ing.', 'explanation': "'avoid' selalu diikuti gerund: 'making'."}]}]

U16_EXERCISES = [{'id': 'u16_ex1', 'unitId': 16, 'page': 51, 'title': 'Latihan 1: Zero Conditional (Kebenaran Ilmiah & Fakta Umum)', 'instruction': 'Pasangkan klausa kondisi (If-clause) dengan fakta umum/ilmiah yang dihasilkan (Zero Conditional: If + Present Simple, Present Simple).', 'type': 'choice', 'questions': [{'q': '1. If you heat water to 100 degrees Celsius, &rarr; [BLANK]', 'options': ['it boils.', 'it freezes.', 'it will evaporate yesterday.', 'it became ice.'], 'answer': 'it boils.', 'hint': 'Air pada suhu 100°C mendidih.', 'explanation': 'Fakta ilmiah: If you heat water to 100°C, it boils.'}, {'q': '2. If you freeze water, &rarr; [BLANK]', 'options': ['it turns into ice.', 'it gets very hot.', 'it boils.', 'it disappears.'], 'answer': 'it turns into ice.', 'hint': 'Air membeku menjadi es.', 'explanation': 'If you freeze water, it turns into ice.'}, {'q': "3. If people don't eat or drink, &rarr; [BLANK]", 'options': ['they die.', 'they get stronger.', 'they feel energetic.', 'they sleep forever.'], 'answer': 'they die.', 'hint': 'Kebutuhan dasar manusia.', 'explanation': "If people don't eat or drink, they die."}, {'q': '4. If you mix yellow and blue, &rarr; [BLANK]', 'options': ['you get green.', 'you get red.', 'you get purple.', 'you get black.'], 'answer': 'you get green.', 'hint': 'Pencampuran warna kuning dan biru.', 'explanation': 'Kuning + biru = hijau: you get green.'}]}, {'id': 'u16_ex2', 'unitId': 16, 'page': 52, 'title': 'Latihan 2: First Conditional (Kemungkinan di Masa Depan)', 'instruction': 'Lengkapi kalimat First Conditional menggunakan pola: If + Present Simple, will + Infinitive.', 'type': 'fill', 'questions': [{'q': '1. If it [BLANK] (rain) tomorrow, we will cancel the picnic.', 'answer': 'rains', 'alternateAnswers': ['Rains'], 'hint': 'Subjek it memakai kata kerja bentuk -s.', 'explanation': "If-clause menggunakan Present Simple: 'rains'."}, {'q': '2. If you study hard, you [BLANK] (pass) the examination.', 'answer': 'will pass', 'alternateAnswers': ["'ll pass", 'Will pass'], 'hint': 'Main clause menggunakan will + V1.', 'explanation': "Main clause: 'will pass'."}, {'q': '3. She will be late if she [BLANK] (not hurry) up.', 'answer': "doesn't hurry", 'alternateAnswers': ['does not hurry', "Doesn't hurry"], 'hint': 'Subjek she dalam bentuk Present Simple negatif.', 'explanation': "If-clause: 'doesn't hurry'."}, {'q': '4. If we [BLANK] (miss) the 8:00 train, we will take the next one.', 'answer': 'miss', 'alternateAnswers': ['Miss'], 'hint': 'Subjek we memakai bentuk dasar kata kerja.', 'explanation': "If-clause: 'miss'."}, {'q': "5. What [BLANK] (you / do) if you don't find your keys?", 'answer': 'will you do', 'alternateAnswers': ['Will you do'], 'hint': 'Kalimat tanya: will + subjek + do.', 'explanation': "Bentuk tanya: 'will you do'."}]}, {'id': 'u16_ex3', 'unitId': 16, 'page': 52, 'title': 'Latihan 3: Memilih if atau unless', 'instruction': "Pilihlah antara 'if' (jika) atau 'unless' (jika tidak / kecuali jika).", 'type': 'choice', 'questions': [{'q': "1. You won't pass the exam [BLANK] you study hard.", 'options': ['unless', 'if'], 'answer': 'unless', 'hint': "Unless you study = If you don't study.", 'explanation': "'unless' berarti 'kecuali jika' / 'jika tidak'."}, {'q': '2. We will go swimming tomorrow [BLANK] the weather is warm.', 'options': ['if', 'unless'], 'answer': 'if', 'hint': 'Syarat positif: jika cuacanya hangat.', 'explanation': "Kondisi positif menggunakan 'if'."}, {'q': "3. He will be angry [BLANK] you don't tell him the truth.", 'options': ['if', 'unless'], 'answer': 'if', 'hint': "Sudah ada kata don't di dalam klausa.", 'explanation': "Karena sudah ada 'don't tell', gunakan 'if'."}, {'q': '4. We will be late [BLANK] we leave right now.', 'options': ['unless', 'if'], 'answer': 'unless', 'hint': 'Kecuali jika kita berangkat sekarang.', 'explanation': "'unless we leave right now' = jika kita tidak segera berangkat."}]}, {'id': 'u16_ex4', 'unitId': 16, 'page': 53, 'title': 'Latihan 4: Menyusun Kata Acak Menjadi Kalimat Pengandaian', 'instruction': 'Susun kata-kata yang diacak menjadi kalimat First Conditional yang tepat.', 'type': 'fill', 'questions': [{'q': '1. rains / stay / it / we / if / will / home', 'answer': 'If it rains we will stay home.', 'alternateAnswers': ['if it rains we will stay home.', 'If it rains, we will stay home.', 'We will stay home if it rains.'], 'hint': "Mulai dengan 'If it rains...'", 'explanation': 'If it rains, we will stay home.'}, {'q': '2. call / will / arrive / I / you / I / when', 'answer': 'I will call you when I arrive.', 'alternateAnswers': ['i will call you when i arrive.', 'When I arrive I will call you.', 'When I arrive, I will call you.'], 'hint': "Mulai dengan 'I will call you...'", 'explanation': 'I will call you when I arrive.'}, {'q': '3. you / feel / better / take / will / medicine / you / if / this', 'answer': 'If you take this medicine you will feel better.', 'alternateAnswers': ['if you take this medicine you will feel better.', 'If you take this medicine, you will feel better.', 'You will feel better if you take this medicine.'], 'hint': "Mulai dengan 'If you take this medicine...'", 'explanation': 'If you take this medicine, you will feel better.'}]}, {'id': 'u16_ex5', 'unitId': 16, 'page': 53, 'title': 'Latihan 5: Melengkapi Dialog First Conditional', 'instruction': 'Lengkapi kalimat dialog tentang rencana liburan dengan bentuk First Conditional yang tepat.', 'type': 'fill', 'questions': [{'q': '1. Amy: What will happen if the flight [BLANK] (be) delayed?', 'answer': 'is', 'alternateAnswers': ['Is'], 'hint': 'Present Simple dari be untuk the flight.', 'explanation': 'If the flight is delayed.'}, {'q': "2. Ben: If it's delayed, we [BLANK] (wait) in the departure lounge.", 'answer': 'will wait', 'alternateAnswers': ["'ll wait", 'Will wait'], 'hint': 'will + wait.', 'explanation': 'We will wait in the lounge.'}, {'q': '3. Amy: And if we arrive late, [BLANK] (the hotel / keep) our room?', 'answer': 'will the hotel keep', 'alternateAnswers': ['Will the hotel keep'], 'hint': 'will + subjek + keep.', 'explanation': 'Will the hotel keep our room?'}, {'q': "4. Ben: Yes, don't worry. I [BLANK] (call) them if there are any changes.", 'answer': 'will call', 'alternateAnswers': ["'ll call", 'Will call'], 'hint': 'will + call.', 'explanation': 'I will call them.'}]}]

U17_EXERCISES = [{'id': 'u17_ex1', 'unitId': 17, 'page': 54, 'title': 'Latihan 1: Klausa Waktu (Time Clauses with when, as soon as, before, after)', 'instruction': 'Ingat aturan penting: Klausa waktu (setelah when, as soon as, before, after) SELALU menggunakan Present Simple, sedangkan klausa utama menggunakan will + V1.', 'type': 'choice', 'questions': [{'q': '1. I will call you as soon as I [BLANK] at the airport.', 'options': ['arrive', 'will arrive', 'arrived', 'am arriving'], 'answer': 'arrive', 'hint': "Setelah 'as soon as' gunakan Present Simple.", 'explanation': "Klausa waktu menggunakan Present Simple: 'arrive'."}, {'q': '2. Before she goes to bed, she [BLANK] the doors.', 'options': ['will lock', 'locks', 'locked', 'is locking'], 'answer': 'will lock', 'hint': 'Klausa utama menggunakan will + V1.', 'explanation': "Klausa utama aksi masa depan menggunakan 'will lock'."}, {'q': '3. We will have dinner after dad [BLANK] home from work.', 'options': ['comes', 'will come', 'came', 'is coming'], 'answer': 'comes', 'hint': "Setelah kata sambung waktu 'after', gunakan Present Simple.", 'explanation': 'After dad comes home (Present Simple).'}, {'q': '4. When I [BLANK] time, I will help you with your project.', 'options': ['have', 'will have', 'had', 'am having'], 'answer': 'have', 'hint': "Klausa 'when' menggunakan Present Simple.", 'explanation': 'When I have time (Present Simple).'}]}, {'id': 'u17_ex2', 'unitId': 17, 'page': 54, 'title': 'Latihan 2: Melengkapi dengan will atau Present Simple', 'instruction': 'Lengkapi kalimat dengan bentuk kata kerja yang tepat (will + V1 pada klausa utama atau Present Simple pada time clause).', 'type': 'fill', 'questions': [{'q': '1. As soon as the rain stops, we [BLANK] (go) for a walk.', 'answer': 'will go', 'alternateAnswers': ["'ll go", 'Will go'], 'hint': 'Klausa utama: will + go.', 'explanation': 'Main clause: we will go for a walk.'}, {'q': '2. I will send you an email when I [BLANK] (receive) the results.', 'answer': 'receive', 'alternateAnswers': ['Receive'], 'hint': 'Time clause (when I): Present Simple.', 'explanation': 'Time clause: when I receive.'}, {'q': '3. Wash your hands before you [BLANK] (eat) your lunch.', 'answer': 'eat', 'alternateAnswers': ['Eat'], 'hint': 'Before you: Present Simple.', 'explanation': 'Before you eat.'}, {'q': '4. He [BLANK] (buy) a new computer when he gets his salary.', 'answer': 'will buy', 'alternateAnswers': ["'ll buy", 'Will buy'], 'hint': 'Klausa utama: will + buy.', 'explanation': 'Main clause: he will buy.'}]}, {'id': 'u17_ex3', 'unitId': 17, 'page': 55, 'title': 'Latihan 3: Menjodohkan Klausa Pengandaian dan Waktu', 'instruction': 'Pasangkan klausa awal (1-4) dengan klausa kelanjutan yang logis (a-d).', 'type': 'choice', 'questions': [{'q': "1. If you don't wear a warm coat, &rarr; [BLANK]", 'options': ['you will catch a cold.', 'I will wash the dishes.', 'as soon as the movie ends.', 'before the train leaves.'], 'answer': 'you will catch a cold.', 'hint': 'Tidak pakai mantel hangat &rarr; masuk angin.', 'explanation': "If you don't wear a warm coat, you will catch a cold."}, {'q': '2. After we finish dinner, &rarr; [BLANK]', 'options': ['I will wash the dishes.', 'you will catch a cold.', 'it boils.', 'if it rains tomorrow.'], 'answer': 'I will wash the dishes.', 'hint': 'Selesai makan malam &rarr; mencuci piring.', 'explanation': 'After we finish dinner, I will wash the dishes.'}, {'q': '3. We must hurry to the platform &rarr; [BLANK]', 'options': ['before the train leaves.', 'unless you study hard.', 'after he will arrive.', 'when it boiled.'], 'answer': 'before the train leaves.', 'hint': 'Cepat-cepat ke peron sebelum kereta berangkat.', 'explanation': 'Before the train leaves.'}, {'q': '4. I will turn off the television &rarr; [BLANK]', 'options': ['as soon as this programme finishes.', 'unless you are happy.', 'if he bought new shoes.', 'when I was tired.'], 'answer': 'as soon as this programme finishes.', 'hint': 'Matikan TV setelah acara selesai.', 'explanation': 'As soon as this programme finishes.'}]}, {'id': 'u17_ex4', 'unitId': 17, 'page': 55, 'title': 'Latihan 4: First Conditional Clauses (Audio TR 23)', 'instruction': 'Dengarkan audio TR 23 yang memuat awal klausa pengandaian (1-6) dan pilihlah kelanjutan klausa yang paling tepat dan logis.', 'type': 'choice', 'audioTrack': 'TR 23', 'questions': [{'q': "1. Audio: 'If he has to work late...' &rarr; [BLANK]", 'options': ["he won't be able to join us for dinner.", 'he bought a new car yesterday.', 'he would fly to Paris.', 'he goes to sleep immediately.'], 'answer': "he won't be able to join us for dinner.", 'hint': 'Jika harus kerja lembur, dia tidak bisa ikut makan malam.', 'explanation': "Audio TR 23 nomor 1: 'If he has to work late... he won't be able to join us for dinner.'"}, {'q': "2. Audio: 'If it's a nice day tomorrow...' &rarr; [BLANK]", 'options': ["we'll go to the beach for a swim.", 'we stayed at home all day.', 'it would be very cold.', "we don't like it."], 'answer': "we'll go to the beach for a swim.", 'hint': 'Jika besok hari cerah, kita pergi ke pantai.', 'explanation': "Audio TR 23 nomor 2: 'If it's a nice day tomorrow... we'll go to the beach.'"}, {'q': "3. Audio: 'If you don't eat properly...' &rarr; [BLANK]", 'options': ["you'll feel tired and get sick.", 'you ate all the food.', 'you would be strong.', 'you are a chef.'], 'answer': "you'll feel tired and get sick.", 'hint': 'Jika tidak makan dengan baik, badan akan lemas/sakit.', 'explanation': "Audio TR 23 nomor 3: 'If you don't eat properly... you'll feel tired and get sick.'"}, {'q': "4. Audio: 'I'll wear a sweater...' &rarr; [BLANK]", 'options': ['if the weather gets chilly tonight.', 'when I bought it last week.', 'unless it was hot.', 'if I had more money.'], 'answer': 'if the weather gets chilly tonight.', 'hint': 'Pakai sweater jika cuaca dingin nanti malam.', 'explanation': "Audio TR 23 nomor 4: 'I'll wear a sweater... if the weather gets chilly.'"}, {'q': "5. Audio: 'We'll have a picnic...' &rarr; [BLANK]", 'options': ["if it doesn't rain on Saturday.", 'because we ate yesterday.', 'if we would like it.', 'unless it is sunny.'], 'answer': "if it doesn't rain on Saturday.", 'hint': 'Piknik jika tidak turun hujan.', 'explanation': "Audio TR 23 nomor 5: 'We'll have a picnic... if it doesn't rain.'"}, {'q': "6. Audio: 'If you're finished with that book...' &rarr; [BLANK]", 'options': ['can I please borrow it?', 'I bought it yesterday.', 'you would read it again.', 'it was very boring.'], 'answer': 'can I please borrow it?', 'hint': 'Jika sudah selesai membaca buku, bolehkah dipinjam?', 'explanation': "Audio TR 23 nomor 6: 'If you're finished with that book... can I please borrow it?'"}]}, {'id': 'u17_ex5', 'unitId': 17, 'page': 55, 'title': 'Latihan 5: Menulis Ulang Kalimat Menggunakan unless', 'instruction': "Tulis ulang kalimat pengandaian negatif berikut menggunakan 'unless' (Ingat: unless = if not).", 'type': 'fill', 'questions': [{'q': "1. If you don't leave now, you will miss the train. &rarr; [BLANK], you will miss the train.", 'answer': 'Unless you leave now', 'alternateAnswers': ['unless you leave now'], 'hint': "Ganti 'If you don't leave now' menjadi 'Unless you leave now'.", 'explanation': 'Unless you leave now, you will miss the train.'}, {'q': "2. If he doesn't apologise, I won't speak to him. &rarr; [BLANK], I won't speak to him.", 'answer': 'Unless he apologises', 'alternateAnswers': ['Unless he apologizes', 'unless he apologises', 'unless he apologizes'], 'hint': "Gunakan kata kerja 'apologises' setelah he.", 'explanation': "Unless he apologises, I won't speak to him."}, {'q': "3. We won't go on a picnic if it isn't sunny. &rarr; We won't go on a picnic [BLANK].", 'answer': 'unless it is sunny', 'alternateAnswers': ["unless it's sunny"], 'hint': "Ganti 'if it isn't sunny' menjadi 'unless it is sunny'.", 'explanation': "We won't go on a picnic unless it is sunny."}]}, {'id': 'u17_ex6', 'unitId': 17, 'page': 56, 'title': 'Latihan 6: Melengkapi dengan as soon as, until, unless, atau when', 'instruction': 'Pilih kata sambung waktu atau pengandaian yang tepat: as soon as (segera setelah), until (sampai), unless (kecuali jika), when (ketika).', 'type': 'choice', 'questions': [{'q': '1. Please wait here [BLANK] the doctor is ready to see you.', 'options': ['until', 'unless', 'as soon as', 'when'], 'answer': 'until', 'hint': 'Menunggu sampai dokter siap.', 'explanation': "'until' = sampai titik waktu tertentu tercapai."}, {'q': '2. I will send you a text message [BLANK] the plane lands.', 'options': ['as soon as', 'until', 'unless', 'before'], 'answer': 'as soon as', 'hint': 'Segera setelah pesawat mendarat.', 'explanation': "'as soon as' = sesegera mungkin setelah kejadian."}, {'q': '3. You cannot drive a car [BLANK] you have a valid driving licence.', 'options': ['unless', 'until', 'as soon as', 'when'], 'answer': 'unless', 'hint': 'Kecuali jika Anda memiliki SIM.', 'explanation': "'unless' = jika tidak memiliki SIM."}, {'q': '4. What will you do [BLANK] you finish high school?', 'options': ['when', 'unless', 'until', 'as soon'], 'answer': 'when', 'hint': 'Ketika Anda lulus nanti.', 'explanation': "'when' = pada saat waktunya tiba."}]}, {'id': 'u17_ex7', 'unitId': 17, 'page': 56, 'title': 'Latihan 7: Bentuk Kata Kerja yang Benar dalam Time Clauses', 'instruction': 'Pilihlah bentuk kata kerja yang benar pada time clause.', 'type': 'choice', 'questions': [{'q': '1. We will leave as soon as Jack [BLANK] his keys.', 'options': ['finds', 'will find', 'found', 'is finding'], 'answer': 'finds', 'hint': "Klausa 'as soon as' membutuhkan Present Simple.", 'explanation': "Jack tunggal &rarr; 'finds'."}, {'q': "2. I'll pay you back when I [BLANK] paid on Friday.", 'options': ['get', 'will get', 'got', 'am getting'], 'answer': 'get', 'hint': "Klausa 'when' membutuhkan Present Simple.", 'explanation': 'When I get paid.'}, {'q': '3. She will stay at home until she [BLANK] completely better.', 'options': ['feels', 'will feel', 'felt', 'is feeling'], 'answer': 'feels', 'hint': "Klausa 'until' menggunakan Present Simple.", 'explanation': 'Until she feels better.'}]}, {'id': 'u17_ex8', 'unitId': 17, 'page': 56, 'title': 'Latihan 8: Melengkapi Dialog Rencana Liburan', 'instruction': 'Lengkapi dialog rencana bepergian berikut dengan bentuk kata kerja yang tepat.', 'type': 'fill', 'questions': [{'q': '1. Lisa: What time will we leave for the airport? Sam: We will leave as soon as the taxi [BLANK] (arrive).', 'answer': 'arrives', 'alternateAnswers': ['Arrives'], 'hint': 'Present Simple untuk the taxi.', 'explanation': 'As soon as the taxi arrives.'}, {'q': '2. Lisa: And what if there [BLANK] (be) heavy traffic on the road?', 'answer': 'is', 'alternateAnswers': ['Is'], 'hint': 'Present Simple dari be untuk traffic (uncountable).', 'explanation': 'What if there is heavy traffic?'}, {'q': '3. Sam: If there is heavy traffic, the driver [BLANK] (take) the ring road instead.', 'answer': 'will take', 'alternateAnswers': ["'ll take", 'Will take'], 'hint': 'Main clause: will + take.', 'explanation': 'The driver will take the ring road.'}, {'q': '4. Lisa: Great! I [BLANK] (call) mum as soon as we check into the hotel.', 'answer': 'will call', 'alternateAnswers': ["'ll call", 'Will call'], 'hint': 'Main clause: will + call.', 'explanation': 'I will call mum as soon as we check into the hotel.'}]}]
